import {categories} from './data.js';

const app=document.querySelector('#app'),toast=document.querySelector('#toast');
const USERS='fq-users-v2',SESSION='fq-session-v2',DATA='fuocoquiz-data-v1',CONFIG='q400vvf-config-v1',ACTIVE_QUIZZES='q400vvf-active-quizzes-v1';
let users=JSON.parse(localStorage.getItem(USERS)||'[]'),currentUser=null,official=[],imported=JSON.parse(localStorage.getItem(DATA)||'[]');
let cloudMode=false,runtimeConfig={},cloudSyncQueue=Promise.resolve(),cloudAdminUsers=[];
const DEFAULT_EXAM_PLAN={storia:8,logica:11,insiemi:1,fisica:6,chimica:6,informatica:4,inglese:4,brani:0};
const EXAM_ORDER=['storia','logica','insiemi','fisica','chimica','informatica','inglese','brani'];
let examConfig=JSON.parse(localStorage.getItem(CONFIG)||'null')||{examPlan:{...DEFAULT_EXAM_PLAN}};
let quiz=null,timerHandle=null,deferredInstall=null,updateCheckedFor=null,updateCheckTimer=null,updatePromptedVersion=null,lastUpdateCheckAt=0;
const EXAM_SECONDS=40*60;
const allQuestions=()=>[...official,...imported];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmtMetric=(value,digits=2)=>value==null?'—':Number(value).toLocaleString('it',{maximumFractionDigits:digits});
const notify=m=>{toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2300)};
async function cloudApi(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});if(!response.ok){let message='Operazione non riuscita';try{const body=await response.json();message=body.detail||body.message||message}catch{}throw Error(message)}if(response.status===204)return null;return response.json()}
function cloudSync(){const record=userRecord();if(!record)return Promise.resolve();const snapshot=JSON.parse(JSON.stringify(record.state||{})),config=currentUser?.role==='admin'?JSON.parse(JSON.stringify(examConfig)):undefined;cloudSyncQueue=cloudSyncQueue.catch(()=>{}).then(()=>cloudApi('./api/cloud/state',{method:'PUT',body:JSON.stringify({state:snapshot,config})}));return cloudSyncQueue}
const portableSync=()=>cloudMode?cloudSync():fetch('./api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({users,imported,config:examConfig})}).catch(()=>{});
const saveUsers=()=>{if(!cloudMode)localStorage.setItem(USERS,JSON.stringify(users));return portableSync()};
const hash=async(s)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(b=>b.toString(16).padStart(2,'0')).join('');
const userRecord=()=>users.find(u=>u.id===currentUser?.id);
const userState=()=>{const u=userRecord();u.state??={};u.state.progress??={};u.state.sessions??=[];u.state.categoryCursor??={};u.state.examCursor??={};u.state.examCount??=0;u.state.quizGenerationCount??=0;u.state.quizRotation??={};u.state.examPresets??=[];u.state.activeExamPresetId??=null;u.state.theme??='system';u.state.deepLearning??={enabled:false,tracks:{}};u.state.deepLearning.tracks??={};u.state.deepLearningIntroSeen??=false;return u.state};
const themeLabel=value=>({light:'Chiaro',dark:'Scuro',system:'Sistema'}[value]||'Sistema');
const currentLogoUrl=()=>runtimeConfig.logoUrl||examConfig.brandLogoDataUrl||'logo-vvf.jpg';
function applyBranding(url=currentLogoUrl()){runtimeConfig.logoUrl=url;document.querySelectorAll('[data-brand-logo]').forEach(image=>{image.src=url});document.querySelector('link[rel="icon"]')?.setAttribute('href',url)}
function applyTheme(value=currentUser?userState().theme:'system'){const selected=['light','dark','system'].includes(value)?value:'system',resolved=selected==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):selected,label=themeLabel(selected);document.documentElement.dataset.theme=resolved;document.documentElement.dataset.themePreference=selected;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',resolved==='dark'?'#0b0b0c':'#b42318');document.querySelectorAll('[data-theme-label]').forEach(element=>element.textContent=label);document.querySelectorAll('[data-theme-cycle]').forEach(button=>{button.setAttribute('aria-label',`Tema attuale: ${label}. Tocca per cambiare`);button.title=`Tema attuale: ${label}. Tocca per cambiare`})}
function cycleTheme(){if(!currentUser)return;const order=['light','dark','system'],state=userState();state.theme=order[(order.indexOf(state.theme)+1)%order.length];applyTheme(state.theme);saveUsers();notify(`Tema: ${themeLabel(state.theme)}`)}
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(!currentUser||userState().theme==='system')applyTheme()});
const persist=()=>{saveUsers()};
const progressFor=id=>userState().progress[id]||{attempts:0,correct:0,wrong:0,skipped:0,status:'unanswered'};
const catName=id=>categories.find(c=>c.id===id)?.name||id;
const normalizePlan=plan=>Object.fromEntries(EXAM_ORDER.map(id=>[id,Math.max(0,Math.floor(Number(plan?.[id])||0))]));
const planTotal=plan=>Object.values(normalizePlan(plan)).reduce((sum,count)=>sum+count,0);
const activeExamPreset=()=>{const st=userState();return st.examPresets.find(item=>item.id===st.activeExamPresetId)||null};
const activeExamPlan=()=>activeExamPreset()?.plan||examConfig.examPlan||DEFAULT_EXAM_PLAN;
const examPlan=()=>EXAM_ORDER.map(id=>[id,normalizePlan(activeExamPlan())[id]]).filter(([,count])=>count>0);
const seedNumber=value=>{let h=2166136261;for(const char of String(value)){h^=char.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
const seededRandom=seed=>{let state=seedNumber(seed)||1;return()=>{state+=0x6D2B79F5;let n=state;n=Math.imul(n^n>>>15,n|1);n^=n+Math.imul(n^n>>>7,n|61);return((n^n>>>14)>>>0)/4294967296}};
function shuffleWithSeed(items,seed){const out=[...items],random=seededRandom(seed);for(let i=out.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function createQuizSeed(kind){const st=userState();st.quizGenerationCount=(Number(st.quizGenerationCount)||0)+1;const now=new Date();return `${now.toISOString()}|${now.getTime()}|${performance.now().toFixed(3)}|${currentUser.id}|${st.quizGenerationCount}|${kind}`}
function takeRotating(source,count,track,cat,sessionSeed){const target=Math.min(Math.max(0,count),source.length);if(!target)return[];const st=userState(),key=`${track}:${cat}`;let rotation=st.quizRotation[key];if(!rotation||rotation.size!==source.length)rotation={seed:`${sessionSeed}|${key}|cycle-0`,cursor:0,cycle:0,size:source.length};const out=[],used=new Set();while(out.length<target){const deck=shuffleWithSeed(source,rotation.seed);while(rotation.cursor<deck.length&&out.length<target){const q=deck[rotation.cursor++];if(!used.has(q.id)){used.add(q.id);out.push(q)}}if(rotation.cursor>=deck.length&&out.length<target){rotation.cycle++;rotation.seed=`${sessionSeed}|${key}|cycle-${rotation.cycle}|${new Date().toISOString()}`;rotation.cursor=0}}st.quizRotation[key]=rotation;return out}
function deepLearningSettings(){return userState().deepLearning}
function guidedCompositionSource(cat,count){const all=allQuestions().filter(q=>q.category===cat),withExplanation=all.filter(q=>q.explanation);return withExplanation.length>=count?withExplanation:all}
function deepLearningBucket(track,cat,source){const settings=deepLearningSettings(),key=`${track}:${cat}`,sourceIds=new Set(source.map(q=>q.id));let bucket=settings.tracks[key];if(!bucket||bucket.size!==source.length){const previous=Array.isArray(bucket?.mastered)?bucket.mastered.filter(id=>sourceIds.has(id)):[];bucket={cycle:Math.max(1,Number(bucket?.cycle)||1),size:source.length,mastered:previous,updatedAt:new Date().toISOString()}}else bucket.mastered=Array.isArray(bucket.mastered)?bucket.mastered.filter(id=>sourceIds.has(id)):[];settings.tracks[key]=bucket;return bucket}
function takeDeepLearning(source,count,track,cat,sessionSeed){const target=Math.min(Math.max(0,count),source.length);if(!target)return[];const bucket=deepLearningBucket(track,cat,source),sourceIds=new Set(source.map(q=>q.id)),mastered=new Set(bucket.mastered.filter(id=>sourceIds.has(id)));if(mastered.size>=source.length){bucket.cycle++;bucket.mastered=[];bucket.completedAt=null;mastered.clear()}const eligible=shuffleWithSeed(source.filter(q=>!mastered.has(q.id)),`${sessionSeed}|deep|${track}|${cat}|cycle-${bucket.cycle}`),out=eligible.slice(0,target),used=new Set(out.map(q=>q.id));if(out.length<target){const fill=shuffleWithSeed(source.filter(q=>!used.has(q.id)),`${sessionSeed}|deep-fill|${track}|${cat}`);out.push(...fill.slice(0,target-out.length))}bucket.updatedAt=new Date().toISOString();return out}
function updateDeepLearningFromRows(rows,track){if(!quiz?.deepLearning)return;const grouped=new Map();for(const row of rows){const q=row.q||allQuestions().find(item=>item.id===row.id);if(q)grouped.set(q.category,[...(grouped.get(q.category)||[]),{...row,q}])}for(const [cat,categoryRows] of grouped){const count=normalizePlan(activeExamPlan())[cat]||categoryRows.length,source=track==='guided-exam'?guidedCompositionSource(cat,count):allQuestions().filter(q=>q.category===cat),bucket=deepLearningBucket(track,cat,source),mastered=new Set(bucket.mastered);for(const row of categoryRows){if(row.correct)mastered.add(row.q.id);else mastered.delete(row.q.id)}bucket.mastered=[...mastered];bucket.updatedAt=new Date().toISOString();bucket.completedAt=bucket.mastered.length>=bucket.size?new Date().toISOString():null}}
function deepLearningTrackSummary(track){let mastered=0,total=0,cycles=[];for(const [cat,count] of examPlan()){const source=track==='guided-exam'?guidedCompositionSource(cat,count):allQuestions().filter(q=>q.category===cat),bucket=deepLearningBucket(track,cat,source),ids=new Set(source.map(q=>q.id));mastered+=bucket.mastered.filter(id=>ids.has(id)).length;total+=source.length;cycles.push(bucket.cycle)}return{mastered,total,cycle:cycles.length?Math.min(...cycles):1}}
const activeQuizMap=()=>{try{return JSON.parse(localStorage.getItem(ACTIVE_QUIZZES)||'{}')}catch{return{}}};
const isTimedFortyQuiz=(value=quiz)=>value?.kind==='exam'||value?.mode==='guided-exam';
const remainingFor=value=>Math.min(EXAM_SECONDS,Math.max(0,EXAM_SECONDS-Math.floor((Date.now()-Number(value.startedAt))/1000)));
function timerMarkup(){return `<div class="exam-timer" data-exam-timer role="timer" aria-label="Tempo rimasto: ${formatTime(quiz.remaining)}"><span class="exam-timer-label">Tempo rimasto</span><strong data-exam-time>${formatTime(quiz.remaining)}</strong><span class="exam-timer-note">La prova termina automaticamente a 00:00</span></div>`}
function updateTimerDisplay(){const remaining=quiz?.remaining??0,value=formatTime(remaining),tone=remaining<=600?'danger':remaining<=1200?'orange':remaining<=1800?'yellow':'green',percent=Math.max(0,Math.min(100,remaining/EXAM_SECONDS*100));app.querySelectorAll('[data-exam-time]').forEach(element=>element.textContent=value);app.querySelectorAll('[data-exam-timer]').forEach(element=>{element.setAttribute('aria-label',`Tempo rimasto: ${value}`);element.classList.remove('green','yellow','orange','danger');element.classList.add(tone);element.style.setProperty('--time-percent',`${percent}%`)})}
function tickFortyMinuteTimer(){if(!isTimedFortyQuiz()||quiz.finished){clearInterval(timerHandle);return}quiz.remaining=remainingFor(quiz);updateTimerDisplay();if(quiz.remaining===0){clearInterval(timerHandle);quiz.kind==='exam'?finishExam('timeout'):finishGuided('timeout')}}
function startFortyMinuteTimer(){clearInterval(timerHandle);tickFortyMinuteTimer();if(quiz&&!quiz.finished&&quiz.remaining>0)timerHandle=setInterval(tickFortyMinuteTimer,1000)}
function saveActiveQuiz(){if(!currentUser||!isTimedFortyQuiz()||quiz.finished)return;quiz.remaining=remainingFor(quiz);const snapshot=JSON.parse(JSON.stringify(quiz)),active=activeQuizMap();active[currentUser.id]=snapshot;localStorage.setItem(ACTIVE_QUIZZES,JSON.stringify(active));userState().activeQuiz=snapshot;saveUsers()}
function clearActiveQuiz(){if(!currentUser)return;const active=activeQuizMap();delete active[currentUser.id];localStorage.setItem(ACTIVE_QUIZZES,JSON.stringify(active));delete userState().activeQuiz;saveUsers()}
function resumeActiveQuiz(){if(!currentUser)return false;const saved=activeQuizMap()[currentUser.id]||userState().activeQuiz;if(!saved)return false;if(!isTimedFortyQuiz(saved)||!Array.isArray(saved.pool)||saved.pool.length!==40||!Number.isInteger(saved.index)||saved.index<0||saved.index>=saved.pool.length||!Number.isFinite(Number(saved.startedAt))){clearActiveQuiz();return false}quiz=saved;quiz.finished=false;quiz.remaining=remainingFor(quiz);if(quiz.remaining===0){quiz.kind==='exam'?finishExam('timeout'):finishGuided('timeout');return true}quiz.kind==='exam'?renderQuestion():renderGuided();startFortyMinuteTimer();return true}
function questionStateAt(index){if(quiz.kind==='exam'){const answered=quiz.answers[index]!==null||(index===quiz.index&&quiz.selected!==null);return {className:answered?'answered':'unanswered',label:answered?'risposta data':'non fatta'}}const q=quiz.pool[index],entry=quiz.history[q.id];if(!entry||entry.blank)return {className:entry?.blank?'blank':'unanswered',label:entry?.blank?'non risposta':'non fatta'};return {className:entry.correct?'correct':'wrong',label:entry.correct?'corretta':'errata'}}
function questionOverviewMarkup(){if(!isTimedFortyQuiz())return'';const legend=quiz.kind==='exam'?'<span><i class="answered"></i>Risposta data</span><span><i class="unanswered"></i>Non fatta</span>':'<span><i class="correct"></i>Corretta</span><span><i class="wrong"></i>Errata</span><span><i class="unanswered"></i>Non fatta</span>';return `<section class="question-overview" aria-label="Panoramica delle 40 domande"><div class="question-overview-head"><b>Panoramica domande</b><span>Tocca un numero per aprirlo</span></div><div class="question-dots">${quiz.pool.map((q,index)=>{const state=questionStateAt(index);return `<button type="button" class="question-dot ${state.className} ${index===quiz.index?'current':''}" data-question-jump="${index}" aria-label="Domanda ${index+1}: ${state.label}" aria-current="${index===quiz.index?'step':'false'}">${index+1}</button>`}).join('')}</div><div class="question-legend">${legend}<span><i class="current"></i>Attuale</span></div></section>`}
function bindQuestionOverview(){app.querySelectorAll('[data-question-jump]').forEach(button=>button.onclick=()=>goToQuestion(Number(button.dataset.questionJump)));const track=app.querySelector('.question-dots'),current=track?.querySelector('.current');if(track&&current)requestAnimationFrame(()=>track.scrollTo({left:Math.max(0,current.offsetLeft-track.clientWidth/2+current.clientWidth/2),behavior:'smooth'}))}
function refreshQuestionOverview(){app.querySelectorAll('[data-question-jump]').forEach((button,index)=>{const state=questionStateAt(index);button.classList.remove('answered','unanswered','blank','correct','wrong');button.classList.add(state.className);button.setAttribute('aria-label',`Domanda ${index+1}: ${state.label}`)})}
function goToQuestion(target){if(!Number.isInteger(target)||target<0||target>=quiz.pool.length||target===quiz.index)return;if(quiz.kind==='exam')quiz.answers[quiz.index]=quiz.selected;quiz.index=target;quiz.selected=quiz.kind==='exam'?quiz.answers[target]:null;saveActiveQuiz();quiz.kind==='exam'?renderQuestion():renderGuided()}
function unansweredCount(){if(quiz.kind==='exam')return quiz.answers.filter((choice,index)=>choice===null&&!(index===quiz.index&&quiz.selected!==null)).length;return quiz.pool.filter(q=>!quiz.history[q.id]||quiz.history[q.id].blank).length}
function requestDeliveryConfirmation(onConfirm){document.querySelector('.delivery-confirm')?.remove();const missing=unansweredCount(),overlay=document.createElement('div');overlay.className='delivery-confirm';overlay.innerHTML=`<div class="delivery-confirm-card" role="dialog" aria-modal="true" aria-labelledby="deliveryConfirmTitle"><div class="eyebrow">Consegna prova</div><h2 id="deliveryConfirmTitle">Sei sicuro di voler chiudere?</h2><p>${missing?`Hai ancora <strong>${missing}</strong> ${missing===1?'domanda non risposta':'domande non risposte'}. Puoi annullare e aprirle dalla panoramica.`:'Hai risposto a tutte le 40 domande.'}</p><div class="quiz-actions"><button class="ghost" type="button" data-cancel-delivery>Continua la prova</button><button class="primary" type="button" data-confirm-delivery>Consegna e chiudi</button></div></div>`;document.body.append(overlay);const close=()=>{document.removeEventListener('keydown',onKey);overlay.remove()},onKey=e=>{if(e.key==='Escape')close()};overlay.querySelector('[data-cancel-delivery]').onclick=close;overlay.querySelector('[data-confirm-delivery]').onclick=()=>{close();onConfirm()};overlay.onclick=e=>{if(e.target===overlay)close()};document.addEventListener('keydown',onKey);overlay.querySelector('[data-cancel-delivery]').focus()}
function finishCurrentQuiz(){if(!isTimedFortyQuiz()||quiz.finished)return;if(quiz.kind==='exam')quiz.answers[quiz.index]=quiz.selected;saveActiveQuiz();requestDeliveryConfirmation(quiz.kind==='exam'?finishExam:finishGuided)}
function requestAbandonQuizConfirmation(onConfirm){document.querySelector('.delivery-confirm')?.remove();const overlay=document.createElement('div');overlay.className='delivery-confirm';overlay.innerHTML=`<div class="delivery-confirm-card abandon-quiz-card" role="dialog" aria-modal="true" aria-labelledby="abandonQuizTitle"><div class="eyebrow">Prova in corso</div><h2 id="abandonQuizTitle">Vuoi cambiare menu?</h2><p>Uscendo da questa schermata <strong>perderai la prova attuale</strong>: non verrà salvata, non entrerà nelle statistiche e non riprenderà più.</p><div class="quiz-actions"><button class="primary" type="button" data-stay-in-quiz>Resta nella prova</button><button class="ghost danger-text" type="button" data-abandon-quiz>Esci e termina</button></div></div>`;document.body.append(overlay);const close=()=>{document.removeEventListener('keydown',onKey);overlay.remove()},onKey=e=>{if(e.key==='Escape')close()};overlay.querySelector('[data-stay-in-quiz]').onclick=close;overlay.querySelector('[data-abandon-quiz]').onclick=()=>{close();onConfirm()};overlay.onclick=e=>{if(e.target===overlay)close()};document.addEventListener('keydown',onKey);overlay.querySelector('[data-stay-in-quiz]').focus()}
function discardActiveQuiz(){clearInterval(timerHandle);clearActiveQuiz();quiz=null}
function guardQuizMenuNavigation(event){const link=event.target.closest('.bottom-nav a,.brand');if(!link||!isTimedFortyQuiz()||quiz.finished)return;const target=link.getAttribute('href');if(!target?.startsWith('#')||target===location.hash)return;event.preventDefault();event.stopImmediatePropagation();requestAbandonQuizConfirmation(()=>{discardActiveQuiz();if(location.hash===target)router();else location.hash=target})}

function nav(route){document.querySelectorAll('.bottom-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));window.scrollTo({top:0,behavior:'instant'})}
function setHeader(){const top=document.querySelector('.topbar'),isAdmin=currentUser?.role==='admin';document.querySelector('[data-admin-nav]')?.classList.toggle('hidden',!isAdmin);top.querySelectorAll('.account').forEach(x=>x.remove());if(currentUser){const wrap=document.createElement('div');wrap.className='account';wrap.innerHTML=`<span>${esc(currentUser.name)}${isAdmin?' · Admin':''}</span><button class="ghost compact theme-button" data-theme-cycle title="Cambia tema">◐ <span data-theme-label>${themeLabel(userState().theme)}</span></button>${cloudMode?'<a class="button ghost compact" href="#account">Account</a>':'<button class="ghost compact update-check-button" data-update-check>Aggiornamenti</button>'}<button class="ghost compact" data-logout>Esci</button>`;top.append(wrap);wrap.querySelector('[data-theme-cycle]')?.addEventListener('click',cycleTheme);wrap.querySelector('[data-update-check]')?.addEventListener('click',()=>checkForUpdates(true));wrap.querySelector('[data-logout]').onclick=logout;applyTheme()}}
function routeTo(h){location.hash=h}
function loginView(){nav('home');setHeader();document.querySelector('.bottom-nav').classList.add('hidden');if(cloudMode){app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="${esc(runtimeConfig.logoUrl||'logo-vvf.jpg')}" alt="Logo del portale"><div class="eyebrow">${esc(runtimeConfig.siteName||'Quiz 400 VVF 2026')}</div><h1>Bentornato</h1><p>Accedi per ritrovare progressi, domande da ripetere e simulazioni su tutti i tuoi dispositivi.</p>${amateurDisclaimerMarkup()}</div><form class="card auth-card" id="authForm"><label>Nome utente<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><button class="primary" type="submit">Accedi</button><div class="auth-links"><a href="#forgot-password">Password dimenticata?</a>${runtimeConfig.registrationEnabled?'<a href="#register">Crea un account</a>':''}</div><p class="meta">${esc(runtimeConfig.privacyNotice||'')}</p></form></section>`;app.querySelector('#authForm').onsubmit=login;return}const first=!users.length;app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="logo-vvf.jpg" alt="Logo del portale"><div class="eyebrow">Quiz 400 VVF 2026</div><h1>${first?'Crea il primo amministratore':'Bentornato'}</h1><p>${first?'Il primo account gestirà gli utenti. I dati restano su questo dispositivo.':'Accedi per ritrovare progressi, domande da ripetere e simulazioni.'}</p>${amateurDisclaimerMarkup()}</div><form class="card auth-card" id="authForm"><label>Nome utente<input name="username" autocomplete="username" required></label>${first?'<label>Nome visualizzato<input name="name" required></label>':''}<label>Password<input name="password" type="password" autocomplete="current-password" minlength="6" required></label><button class="primary" type="submit">${first?'Crea amministratore':'Accedi'}</button><p class="meta">${first?'La password deve avere almeno 6 caratteri.':'Gli account sono creati da un amministratore.'}</p></form></section>`;app.querySelector('#authForm').onsubmit=first?bootstrapAdmin:login}
async function bootstrapAdmin(e){e.preventDefault();const f=new FormData(e.currentTarget),username=String(f.get('username')).trim().toLowerCase();if(!username)return;const u={id:crypto.randomUUID(),username,name:String(f.get('name')).trim(),role:'admin',passwordHash:await hash(String(f.get('password'))),createdAt:new Date().toISOString(),active:true,state:{progress:{},sessions:[],categoryCursor:{},examCursor:{},examCount:0,deepLearning:{enabled:false,tracks:{}}}};users=[u];saveUsers();signIn(u)}
async function login(e){e.preventDefault();const f=new FormData(e.currentTarget);if(cloudMode){try{const result=await cloudApi('./api/auth/login',{method:'POST',body:JSON.stringify({username:String(f.get('username')).trim(),password:String(f.get('password'))})});examConfig=result.config||examConfig;signIn(result.user)}catch(error){notify(error.message)}return}const u=users.find(x=>x.username===String(f.get('username')).trim().toLowerCase());if(!u||!u.active||u.passwordHash!==await hash(String(f.get('password'))))return notify('Credenziali non valide');signIn(u)}
function signIn(u){if(cloudMode)users=[u];currentUser={id:u.id,name:u.name,username:u.username,email:u.email,role:u.role,mustChangePassword:Boolean(u.mustChangePassword)};updatePromptedVersion=null;if(!cloudMode)sessionStorage.setItem(SESSION,u.id);applyTheme();document.querySelector('.bottom-nav').classList.remove('hidden');setHeader();routeTo(currentUser.mustChangePassword?'change-password':'home');router();startAutomaticUpdateChecks();setTimeout(maybeShowDeepLearningIntro,500)}
async function logout(){clearInterval(timerHandle);clearInterval(updateCheckTimer);quiz=null;if(cloudMode){try{await portableSync();await cloudApi('./api/auth/logout',{method:'POST'})}catch{}}currentUser=null;users=cloudMode?[]:users;updateCheckedFor=null;updatePromptedVersion=null;sessionStorage.removeItem(SESSION);location.hash='login';loginView()}

function showUpdateNotice(info){document.querySelector('[data-update-dialog]')?.remove();const dialog=document.createElement('div');dialog.className='update-dialog-backdrop';dialog.dataset.updateDialog='';dialog.innerHTML=`<section class="card update-dialog" role="dialog" aria-modal="true" aria-labelledby="updateTitle"><div class="eyebrow">Aggiornamento disponibile</div><h2 id="updateTitle">Quiz 400 VVF 2026 ${esc(info.latestVersion)}</h2><p>È disponibile una versione più recente della ${esc(info.currentVersion)} installata.</p><p><b>I tuoi dati non andranno persi:</b> prima dell’installazione viene creato un backup automatico e la cartella <i>portable-data</i> resta intatta.</p><div class="quiz-actions"><button class="primary" data-update-now>Aggiorna ora</button><button class="ghost" data-update-close>Più tardi</button>${info.releaseUrl?`<a class="button ghost" href="${esc(info.releaseUrl)}" target="_blank" rel="noopener">Note della release</a>`:''}</div></section>`;document.body.append(dialog);dialog.querySelector('[data-update-now]').onclick=()=>startInAppUpdate(info,dialog);dialog.querySelector('[data-update-close]').onclick=()=>dialog.remove();dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.remove()})}
async function startInAppUpdate(info,dialog){const panel=dialog.querySelector('.update-dialog');panel.innerHTML=`<div class="update-spinner" aria-hidden="true"></div><div class="eyebrow">Aggiornamento in corso</div><h2>Installazione della versione ${esc(info.latestVersion)}</h2><p>Non chiudere questa pagina. L’app crea il backup, installa la nuova versione e si riavvia automaticamente.</p><p class="meta" data-update-progress>Avvio dell’aggiornamento…</p>`;try{const response=await fetch('./api/update-start',{method:'POST',cache:'no-store'});if(response.status===409){panel.querySelector('[data-update-progress]').textContent='L’app risulta già aggiornata. Ricarico la pagina…';setTimeout(()=>location.reload(),900);return}if(!response.ok)throw Error();panel.querySelector('[data-update-progress]').textContent='Download e installazione in corso…';await waitForUpdatedApp(info.latestVersion,panel)}catch{panel.innerHTML=`<div class="eyebrow">Aggiornamento non avviato</div><h2>Riprova tra poco</h2><p>Controlla la connessione oppure usa il file Aggiorna incluso nella cartella dell’app.</p><div class="quiz-actions"><button class="primary" data-update-close>Chiudi</button></div>`;panel.querySelector('[data-update-close]').onclick=()=>dialog.remove()}}
async function waitForUpdatedApp(expectedVersion,panel){const deadline=Date.now()+300000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,1800));try{const response=await fetch(`./api/update-check?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)continue;const status=await response.json();if(status.currentVersion===expectedVersion&&!status.updateAvailable){panel.innerHTML=`<div class="eyebrow">Aggiornamento completato</div><h2>Versione ${esc(expectedVersion)} installata</h2><p>I dati personali sono al sicuro. Ora svuota la vecchia cache e carica i file nuovi.</p><div class="quiz-actions"><button class="primary" data-refresh-updated-app>Ricarica e aggiorna cache</button></div>`;panel.querySelector('[data-refresh-updated-app]').onclick=()=>refreshApplicationCache(panel);return}}catch{}}throw Error('timeout')}
async function refreshApplicationCache(panel){const button=panel.querySelector('[data-refresh-updated-app]');if(button){button.disabled=true;button.textContent='Aggiornamento cache…'}try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('quiz400vvf-')).map(key=>caches.delete(key)))}if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.getRegistration();await registration?.update()}}catch{}const target=new URL('./',location.href);target.searchParams.set('updated',Date.now());target.hash='home';location.replace(target.href)}
async function checkForUpdates(manual=false,periodic=false){if(!currentUser)return;if(!manual&&!periodic&&updateCheckedFor===currentUser.id)return;if(periodic&&Date.now()-lastUpdateCheckAt<300000)return;if(!manual&&!periodic)updateCheckedFor=currentUser.id;lastUpdateCheckAt=Date.now();if(manual)notify('Controllo aggiornamenti…');try{const response=await fetch(`./api/update-check?t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw Error();const info=await response.json();if(info.updateAvailable){if(manual||updatePromptedVersion!==info.latestVersion){updatePromptedVersion=info.latestVersion;showUpdateNotice(info)}}else if(manual)notify(`Versione ${info.currentVersion}: l’app è aggiornata`)}catch{if(manual)notify('Controllo aggiornamenti non disponibile')}}
function startAutomaticUpdateChecks(){clearInterval(updateCheckTimer);if(!currentUser||cloudMode)return;checkForUpdates(false);updateCheckTimer=setInterval(()=>checkForUpdates(false,true),15*60*1000)}

function summary(){const vals=Object.values(userState().progress);return {answered:vals.filter(x=>x.attempts).length,known:vals.filter(x=>x.status==='known').length,review:vals.filter(x=>x.status==='review').length,unknown:vals.filter(x=>x.status==='unknown').length}}
function categoryMetrics(category='all'){
 const questions=allQuestions().filter(q=>category==='all'||q.category===category),counts={known:0,review:0,unknown:0,unanswered:0};let attempts=0,correctAttempts=0,wrongAttempts=0,skipped=0;
 for(const q of questions){const p=progressFor(q.id),status=['known','review','unknown'].includes(p.status)?p.status:'unanswered';counts[status]++;attempts+=Number(p.attempts)||0;correctAttempts+=Number(p.correct)||0;wrongAttempts+=Number(p.wrong)||0;skipped+=Number(p.skipped)||0}
 const answered=counts.known+counts.review+counts.unknown,graded=correctAttempts+wrongAttempts;
 return {category,total:questions.length,...counts,answered,toDo:counts.unanswered,attempts,correctAttempts,wrongAttempts,skipped,coverage:questions.length?Math.round(answered/questions.length*100):0,accuracy:graded?Math.round(correctAttempts/graded*100):null};
}
const coverageLabel=metrics=>metrics.answered&&metrics.coverage===0?'Meno dell’1%':`${metrics.coverage}%`;
function pieChartMarkup(metrics,title='Situazione domande'){
 const total=Math.max(1,metrics.total),known=metrics.known/total*100,review=metrics.review/total*100,unknown=metrics.unknown/total*100,toDo=metrics.toDo/total*100;
 return `<section class="card mastery-summary"><div class="mastery-copy"><div class="eyebrow">${esc(title)}</div><h2>${coverageLabel(metrics)} completato</h2><p>${metrics.accuracy===null?'Completa le prime domande per calcolare la precisione.':`Precisione sulle risposte date: <strong>${metrics.accuracy}%</strong>.`}</p><div class="mastery-legend"><span><i class="known"></i><b>${metrics.known}</b> Le so</span><span><i class="review"></i><b>${metrics.review}</b> Da ripetere</span><span><i class="unknown"></i><b>${metrics.unknown}</b> Non le so</span><span><i class="unanswered"></i><b>${metrics.toDo}</b> Da fare</span></div></div><div class="mastery-pie" role="img" aria-label="${metrics.known} note, ${metrics.review} da ripetere, ${metrics.unknown} non note, ${metrics.toDo} da fare" style="--pie-known:${known}%;--pie-review:${known+review}%;--pie-unknown:${known+review+unknown}%;--pie-todo:${known+review+unknown+toDo}%"><span><b>${metrics.answered}</b><small>su ${metrics.total}</small></span></div></section>`;
}
function rowsByCategory(rows){const result={};for(const row of rows){const q=row.q||row,category=q.category||row.category;if(!category)continue;const bucket=result[category]??={correct:0,wrong:0,blank:0,total:0};bucket.total++;if(row.blank)bucket.blank++;else if(row.correct)bucket.correct++;else bucket.wrong++}for(const bucket of Object.values(result)){const answered=bucket.correct+bucket.wrong;bucket.accuracy=answered?Math.round(bucket.correct/answered*100):null}return result}
function recordSession(type,rows,extra={}){const correct=rows.filter(row=>row.correct).length,wrong=rows.filter(row=>!row.correct&&!row.blank).length,blank=rows.filter(row=>row.blank).length,answered=correct+wrong,perCategory=rowsByCategory(rows),category=Object.keys(perCategory).length===1?Object.keys(perCategory)[0]:null,session={type,at:new Date().toISOString(),correct,wrong,blank,score:scoreFor(correct,wrong),accuracy:answered?Math.round(correct/answered*100):null,questionCount:rows.length,category,perCategory,...extra};userState().sessions.push(session);return session}
const sessionTypeLabel=type=>({study:'Quiz ordinato per materia',guided:'Quiz guidato per materia','guided-exam':'Prova guidata 40',exam:'Simulazione ufficiale 40'}[type]||'Quiz');
function categorySessions(category){return userState().sessions.map(session=>{const result=session.perCategory?.[category];if(result)return {...session,...result,score:scoreFor(result.correct,result.wrong),category};if(session.category===category)return session;return null}).filter(Boolean)}
function sessionSummary(types){const rows=userState().sessions.filter(session=>types.includes(session.type)),accuracies=rows.map(session=>Number(session.accuracy)).filter(Number.isFinite),scores=rows.map(session=>Number(session.score)).filter(Number.isFinite);return {count:rows.length,averageAccuracy:accuracies.length?Math.round(accuracies.reduce((sum,value)=>sum+value,0)/accuracies.length):null,bestScore:scores.length?Math.max(...scores):null,rows}}
function weaknessInsights(){return categories.map(category=>{const metrics=categoryMetrics(category.id),graded=metrics.correctAttempts+metrics.wrongAttempts,errorRate=graded?metrics.wrongAttempts/graded:0,weakKnown=metrics.known+metrics.review+metrics.unknown,weakRate=weakKnown?(metrics.review+metrics.unknown)/weakKnown:0,priority=Math.round(errorRate*55+weakRate*35+(metrics.toDo/Math.max(1,metrics.total))*10),target=metrics.unknown?'unknown':metrics.review?'review':'unanswered';return {category,metrics,priority,target}}).filter(item=>item.metrics.attempts>0&&item.priority>0).sort((a,b)=>b.priority-a.priority)}
function targetedRecommendationsMarkup(limit=3){const items=weaknessInsights().slice(0,limit);if(!items.length)return `<div class="card targeted-empty"><h3>Esercitazioni mirate</h3><p class="meta">Completa qualche quiz: l’app confronterà errori, precisione e livello di padronanza per individuare le materie da rinforzare.</p></div>`;return `<section class="targeted-section"><div class="section-head"><div><div class="eyebrow">Analisi automatica</div><h2>Esercitazioni consigliate</h2></div></div><div class="targeted-grid">${items.map((item,index)=>`<article class="card targeted-card"><span class="priority-badge">Priorità ${index+1}</span><h3>${esc(item.category.name)}</h3><p><b>${item.metrics.accuracy??0}%</b> di precisione · ${item.metrics.review} da ripetere · ${item.metrics.unknown} non note</p><a class="button ${index?'ghost':'primary'}" href="#targeted/${item.category.id}:${item.target}">Esercitazione mirata</a></article>`).join('')}</div></section>`}
function sessionHistoryMarkup(rows,empty='Nessun quiz completato.') {return rows.length?rows.slice(-8).reverse().map(session=>`<div class="card history quiz-history"><div><b>${esc(sessionTypeLabel(session.type))}</b><small>${session.category?` · ${esc(catName(session.category))}`:''}<br>${new Date(session.at).toLocaleString('it')}</small></div><span>${session.accuracy??'—'}% · ${session.correct||0}✓ ${session.wrong||0}✕ ${session.blank||0}— · ${Number(session.score||0).toLocaleString('it')} pt</span></div>`).join(''):`<div class="card meta">${empty}</div>`}
function explanationMarkup(text){return `<details class="explanation-details"><summary><span>Mostra spiegazione</span><span class="explanation-chevron" aria-hidden="true">⌄</span></summary><div class="explanation-copy">${text?esc(text):'Spiegazione non disponibile per questo quesito.'}</div></details>`}
function home(){nav('home');const s=summary();app.innerHTML=`<section class="hero"><div class="eyebrow">400 Vigili del Fuoco · 11.070 quesiti</div><h1>Studia tutto. Ricorda meglio.</h1><p>Segui ogni materia nell’ordine originale, riprendi da dove eri arrivato e concentra il ripasso sui punti deboli.</p><div class="hero-actions"><a class="button secondary" href="#categories">Continua un argomento</a><a class="button ghost light" href="#simulation">Prova 40/40</a></div></section><div class="section-head"><h2>La tua preparazione</h2></div><div class="stat-row four"><div class="card stat"><strong>${s.answered}</strong><span class="meta">Fatte</span></div><div class="card stat"><strong>${s.known}</strong><span class="meta">Le so</span></div><div class="card stat"><strong>${s.review}</strong><span class="meta">Ripetere</span></div><div class="card stat"><strong>${s.unknown}</strong><span class="meta">Non so</span></div></div><div class="quick-grid"><a class="card quick" href="#review/review"><b>Da ripetere</b><span>Rivedi quelle incerte</span></a><a class="card quick" href="#review/unknown"><b>Non le so</b><span>Lavora sugli errori</span></a><a class="card quick" href="#review/unanswered"><b>Non risposte</b><span>Completa la banca dati</span></a><a class="card quick accent" href="#simulation"><b>Simulazione</b><span>40 domande · 40 minuti</span></a></div>${targetedRecommendationsMarkup(1)}${currentUser.role==='admin'?'<div class="section-head"><h2>Amministrazione</h2></div><a class="card category" href="#settings"><h3>Impostazioni e utenti</h3><p class="meta">Gestisci account, prove, backup e aggiornamenti.</p></a>':''}`}
function categoryCards(){return `<div class="grid">${categories.map(c=>{const qs=allQuestions().filter(q=>q.category===c.id),done=qs.filter(q=>progressFor(q.id).attempts).length,p=Math.round(done/qs.length*100);return `<a class="card category" href="#category/${c.id}"><div class="cat-icon">${c.icon}</div><h3>${c.name}</h3><div class="meta">${done.toLocaleString('it')}/${qs.length.toLocaleString('it')} completate</div><div class="progress"><span style="width:${p}%"></span></div><small>${p}% · riprendi dalla n. ${Math.min(done+1,qs.length)}</small></a>`}).join('')}</div>`}
function categoriesView(){nav('categories');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Percorso completo e ordinato</div><h1>Tutte le materie</h1></div></div>${categoryCards()}`}
function categoryView(id){nav('categories');const c=categories.find(x=>x.id===id);if(!c)return categoriesView();const metrics=categoryMetrics(id),sessions=categorySessions(id);app.innerHTML=`<div class="section-head"><div><div class="eyebrow">${metrics.answered}/${metrics.total} classificate</div><h1>${c.name}</h1></div></div>${pieChartMarkup(metrics,`Statistiche ${c.name}`)}<div class="card"><h2>Percorso completo</h2><p>Le domande vengono presentate nell’ordine originale. Puoi interrompere e riprendere dalla prima non risposta.</p><div class="quiz-actions"><button class="primary" data-resume>${metrics.toDo<metrics.total?'Riprendi dalla prima non fatta':'Inizia dalla domanda 1'}</button><button class="ghost" data-start>Ricomincia dalla n. 1</button></div></div><div class="card guided-card"><div class="mode-title"><span class="mode-icon">✓</span><div><h2>Quiz guidato</h2><p>Stile quiz ufficiale, con esito, risposta corretta e spiegazione subito dopo ogni risposta. Ogni errore entra subito in “Da ripetere”.</p></div></div><div class="guided-options"><button class="secondary" data-guided="15">15 domande</button><button class="secondary" data-guided="30">30 domande</button><button class="secondary" data-guided="50">50 domande</button></div></div><div class="filter-row"><button class="status-chip known" data-filter="known">Le so (${metrics.known})</button><button class="status-chip review" data-filter="review">Da ripetere (${metrics.review})</button><button class="status-chip unknown" data-filter="unknown">Non le so (${metrics.unknown})</button><button class="status-chip unanswered" data-filter="unanswered">Da fare (${metrics.toDo})</button></div><div class="section-head"><h2>Risultati dei quiz di ${c.name}</h2></div>${sessionHistoryMarkup(sessions,'Non hai ancora completato quiz in questa materia.')}`;app.querySelector('[data-resume]').onclick=()=>startCategory(id,'resume');app.querySelector('[data-start]').onclick=()=>startCategory(id,'start');app.querySelectorAll('[data-guided]').forEach(b=>b.onclick=()=>startGuided(id,+b.dataset.guided));app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>startFiltered(id,b.dataset.filter))}
function startCategory(cat,mode){const pool=allQuestions().filter(q=>q.category===cat);let index=0;if(mode==='resume'){const found=pool.findIndex(q=>progressFor(q.id).status==='unanswered');index=found<0?0:found}quiz={kind:'study',pool,index,history:{},selected:null,sourceCategory:cat};renderQuestion()}
function startGuided(cat,count){const seed=createQuizSeed(`guided-${cat}`),source=allQuestions().filter(q=>q.category===cat),selected=takeRotating(source,count,'guided-category',cat,seed),pool=shuffleWithSeed(selected,`${seed}|questions`).map(q=>shuffleGuidedAnswers(q,`${seed}|answers|${q.id}`));persist();quiz={kind:'guided',pool,index:0,history:{},selected:null,sourceCategory:cat,generatedAt:new Date().toISOString()};renderGuided()}
function shuffleGuidedAnswers(q,seed=`${Date.now()}|${q.id}`){const indexed=shuffleWithSeed(q.answers.map((text,index)=>({text,index})),seed);return {...q,answers:indexed.map(x=>x.text),correct:indexed.findIndex(x=>x.index===q.correct)}}
function renderGuided(){const q=quiz.pool[quiz.index],h=quiz.history[q.id],selected=h?.choice??null,completed=h&&!h.blank,last=quiz.index===quiz.pool.length-1;app.innerHTML=`<div class="trainer-title">Esercitazione in modalità Trainer</div>${quiz.mode==='guided-exam'?timerMarkup()+questionOverviewMarkup():''}<div class="quiz-head"><strong>Domanda n.${quiz.index+1} di ${quiz.pool.length} - ${catName(q.category)}</strong><span>${quiz.index+1}/${quiz.pool.length}</span></div><h1 class="question">${esc(q.text)}</h1>${q.image?`<img class="question-image" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="answers">${q.answers.map((a,i)=>`<button class="answer ${completed?(i===q.correct?'correct':i===selected?'wrong':''):''}" data-guided-answer="${i}" ${completed?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>${completed?`<div class="feedback trainer-feedback"><strong>${h.correct?'Risposta ESATTA!':`Risposta SBAGLIATA! La risposta corretta era la ${String.fromCharCode(65+q.correct)}.`}</strong>${explanationMarkup(q.explanation)}</div>`:''}<div class="quiz-actions nav-actions">${quiz.mode==='guided-exam'&&!last?'<button class="ghost danger-text" data-finish-now>Termina prova</button>':''}${quiz.index>0?'<button class="ghost" data-guided-prev>← Indietro</button>':''}${!completed?`<button class="ghost" data-guided-skip>${last&&quiz.mode==='guided-exam'?'Consegna senza risposta':'Tralascia domanda'}</button>`:''}${completed?`<button class="primary" data-guided-next>${last&&quiz.mode==='guided-exam'?'Consegna prova':last?'Termina':'Continua →'}</button>`:''}</div>`;app.querySelectorAll('[data-guided-answer]').forEach(b=>b.onclick=()=>guidedAnswer(+b.dataset.guidedAnswer));app.querySelector('[data-finish-now]')?.addEventListener('click',finishCurrentQuiz);app.querySelector('[data-guided-prev]')?.addEventListener('click',guidedPrevious);app.querySelector('[data-guided-skip]')?.addEventListener('click',guidedSkip);app.querySelector('[data-guided-next]')?.addEventListener('click',guidedNext);bindQuestionOverview()}
function guidedAnswer(choice){const q=quiz.pool[quiz.index],ok=choice===q.correct;quiz.history[q.id]={choice,blank:false,correct:ok,q};if(isTimedFortyQuiz())saveActiveQuiz();else{const p=progressFor(q.id);p.attempts++;if(ok){p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{p.wrong++;p.status='review'}p.lastAt=new Date().toISOString();userState().progress[q.id]=p;persist()}renderGuided()}
function guidedSkip(){const q=quiz.pool[quiz.index],alreadyBlank=quiz.history[q.id]?.blank;quiz.history[q.id]={choice:null,blank:true,correct:false,q};if(isTimedFortyQuiz())saveActiveQuiz();else{const p=progressFor(q.id);if(!alreadyBlank)p.skipped++;if(!p.attempts)p.status='unanswered';p.lastAt=new Date().toISOString();userState().progress[q.id]=p;persist()}guidedNext()}
function guidedPrevious(){if(quiz.index>0){quiz.index--;saveActiveQuiz();renderGuided()}}
function guidedNext(){if(quiz.index===quiz.pool.length-1){if(quiz.mode==='guided-exam'){saveActiveQuiz();requestDeliveryConfirmation(finishGuided);return}return finishGuided()}quiz.index++;saveActiveQuiz();renderGuided()}
function finishGuided(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),correct=rows.filter(x=>x.correct).length,wrong=rows.filter(x=>!x.correct&&!x.blank).length,blank=rows.filter(x=>x.blank).length,score=scoreFor(correct,wrong);userState().sessions.push({type:'guided',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=resultCard('Prova guidata completata',correct,wrong,blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})}
function startFiltered(cat,status){const pool=allQuestions().filter(q=>(cat==='all'||q.category===cat)&&progressFor(q.id).status===status);if(!pool.length)return notify('Nessuna domanda in questo gruppo');quiz={kind:'study',pool,index:0,history:{},selected:null,filter:status,sourceCategory:cat==='all'?null:cat};renderQuestion()}
function reviewView(status){nav('stats');startFiltered('all',status)}
function targetedView(param){nav('stats');const [category,status]=String(param||'').split(':');if(!categories.some(item=>item.id===category)||!['known','review','unknown','unanswered'].includes(status))return statsView();startFiltered(category,status)}

function renderQuestion(){const q=quiz.pool[quiz.index],p=progressFor(q.id),selected=quiz.selected,isStudy=quiz.kind==='study',last=quiz.index===quiz.pool.length-1;app.innerHTML=`${!isStudy?timerMarkup()+questionOverviewMarkup():''}<div class="quiz-head"><div><span class="meta">${isStudy?'Studio ordinato':'Simulazione a tempo'}</span><br><strong>${catName(q.category)}</strong></div><strong>${quiz.index+1}/${quiz.pool.length}</strong></div><div class="progress"><span style="width:${(quiz.index+1)/quiz.pool.length*100}%"></span></div><h1 class="question">${esc(q.text)}</h1>${q.image?`<img class="question-image" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="answers">${q.answers.map((a,i)=>`<button class="answer ${selected!==null&&isStudy?(i===q.correct?'correct':i===selected?'wrong':''):selected===i?'picked':''}" data-answer="${i}" ${selected!==null&&isStudy?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(a)}</span></button>`).join('')}</div>${selected!==null&&isStudy?`<div class="feedback"><strong>${selected===q.correct?'Risposta corretta':'Risposta errata · aggiunta a Da ripetere'}</strong>${explanationMarkup(q.explanation)}<p>Come la consideri?</p><div class="mastery"><button class="status-chip known" data-status="known">La so</button><button class="status-chip review" data-status="review">Da ripetere</button><button class="status-chip unknown" data-status="unknown">Non la so</button></div></div>`:''}<div class="quiz-actions nav-actions">${!isStudy&&!last?'<button class="ghost danger-text" data-finish-now>Termina prova</button>':''}${quiz.index>0?'<button class="ghost" data-prev>← Indietro</button>':''}<button class="ghost" data-skip>${isStudy?'Segna non risposta':'Lascia in bianco'}</button>${selected!==null&&isStudy?'<button class="primary" data-next>Prossima →</button>':''}${!isStudy?`<button class="primary" data-exam-next>${last?'Consegna prova':'Conferma e avanti →'}</button>`:''}</div><div class="question-state">Stato attuale: <b>${statusLabel(p.status)}</b></div>`;app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>selectAnswer(+b.dataset.answer));app.querySelector('[data-finish-now]')?.addEventListener('click',finishCurrentQuiz);app.querySelector('[data-prev]')?.addEventListener('click',previous);app.querySelector('[data-skip]').onclick=skip;app.querySelector('[data-next]')?.addEventListener('click',next);app.querySelector('[data-exam-next]')?.addEventListener('click',examNext);app.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>markStatus(b.dataset.status));bindQuestionOverview()}
function selectAnswer(choice){if(quiz.kind==='study'){quiz.selected=choice;recordStudy(choice);renderQuestion()}else{quiz.selected=choice;app.querySelectorAll('.answer').forEach((b,i)=>b.classList.toggle('picked',i===choice));refreshQuestionOverview();saveActiveQuiz()}}
function recordStudy(choice){const q=quiz.pool[quiz.index],p=progressFor(q.id),ok=choice===q.correct;if(!quiz.history[q.id]){p.attempts++;ok?p.correct++:p.wrong++}p.status=ok?(p.correct>=2&&p.wrong===0?'known':'review'):'review';p.lastAt=new Date().toISOString();userState().progress[q.id]=p;quiz.history[q.id]={choice,blank:false,correct:ok,q};persist()}
function markStatus(status){const q=quiz.pool[quiz.index],p=progressFor(q.id);p.status=status;userState().progress[q.id]=p;persist();notify(`Segnata: ${statusLabel(status)}`);next()}
function skip(){const q=quiz.pool[quiz.index];if(quiz.kind==='study'){const p=progressFor(q.id);if(!quiz.history[q.id])p.skipped++;p.status='unanswered';p.lastAt=new Date().toISOString();userState().progress[q.id]=p;quiz.history[q.id]={choice:null,blank:true,correct:false,q};persist();next()}else{quiz.selected=null;examNext()}}
function previous(){if(quiz.index<=0)return;if(quiz.kind==='exam')quiz.answers[quiz.index]=quiz.selected;quiz.index--;const q=quiz.pool[quiz.index];quiz.selected=quiz.kind==='exam'?quiz.answers[quiz.index]:(quiz.history[q.id]?.choice??null);saveActiveQuiz();renderQuestion()}
function next(){quiz.index++;quiz.selected=null;if(quiz.index>=quiz.pool.length)return finishStudy();const q=quiz.pool[quiz.index];quiz.selected=quiz.history[q.id]?.choice??null;renderQuestion()}
function finishStudy(){if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),correct=rows.filter(x=>x.correct).length,wrong=rows.filter(x=>!x.correct&&!x.blank).length,blank=rows.filter(x=>x.blank).length,score=scoreFor(correct,wrong);userState().sessions.push({type:'study',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=resultCard('Quiz completato',correct,wrong,blank,'<a class="button primary" href="#categories">Materie</a><a class="button ghost" href="#stats">Progressi</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})}
const statusLabel=s=>({known:'La so',review:'Da ripetere',unknown:'Non la so',unanswered:'Non risposta'}[s]||'Non risposta');

function simulationView(){nav('simulation');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card"><h2>Simulazione a tempo</h2><p>40 domande in 40 minuti. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card composition guided-exam-card"><h2>Prova guidata con spiegazioni</h2><p>Stesse 40 domande e stessa composizione, ma dopo ogni risposta vedi subito esito, soluzione corretta e spiegazione.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div><div class="card composition"><h2>Composizione identica per entrambe</h2><p><b>8</b> Storia · <b>11</b> Logica · <b>1</b> Insiemi · <b>6</b> Fisica · <b>6</b> Chimica · <b>4</b> Informatica · <b>4</b> Inglese</p></div>`;app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam}
function startGuidedExam(){const seed=createQuizSeed('guided-exam'),plan=examPlan(),deepLearning=deepLearningSettings().enabled,selected=plan.flatMap(([cat,count])=>deepLearning?takeDeepLearning(guidedCompositionSource(cat,count),count,'guided-exam',cat,seed):takeGuidedComposition(cat,count,seed)),pool=shuffleWithSeed(selected,`${seed}|questions`).map(q=>shuffleGuidedAnswers(q,`${seed}|answers|${q.id}`));userState().examCount++;persist();quiz={kind:'guided',mode:'guided-exam',deepLearning,pool,index:0,history:{},selected:null,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderGuided();startFortyMinuteTimer()}
function takeGuidedComposition(cat,count,seed){return takeRotating(guidedCompositionSource(cat,count),count,'guided-exam',cat,seed)}
function startExam(){const seed=createQuizSeed('exam'),plan=examPlan(),deepLearning=deepLearningSettings().enabled,selected=plan.flatMap(([cat,count])=>{const source=allQuestions().filter(q=>q.category===cat);return deepLearning?takeDeepLearning(source,count,'exam',cat,seed):takeRotating(source,count,'exam',cat,seed)}),pool=shuffleWithSeed(selected,`${seed}|questions`);userState().examCount++;persist();quiz={kind:'exam',deepLearning,pool,index:0,answers:Array(pool.length).fill(null),selected:null,remaining:EXAM_SECONDS,startedAt:Date.now(),generatedAt:new Date().toISOString()};saveActiveQuiz();renderQuestion();startFortyMinuteTimer()}
function examNext(){quiz.answers[quiz.index]=quiz.selected;if(quiz.index===quiz.pool.length-1){saveActiveQuiz();requestDeliveryConfirmation(finishExam);return}quiz.index++;quiz.selected=null;saveActiveQuiz();renderQuestion()}
function finishExam(){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map((q,i)=>({id:q.id,category:q.category,q,choice:quiz.answers[i],correct:quiz.answers[i]===q.correct,blank:quiz.answers[i]===null}));let correct=0,wrong=0,blank=0;for(const r of rows){const p=progressFor(r.id);if(r.blank){blank++;p.skipped++;if(!p.attempts)p.status='unanswered'}else{p.attempts++;if(r.correct){correct++;p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{wrong++;p.wrong++;p.status='review'}}p.lastAt=new Date().toISOString();userState().progress[r.id]=p}const score=Math.round((correct-wrong*.33)*100)/100;userState().sessions.push({type:'exam',at:new Date().toISOString(),correct,wrong,blank,score});persist();app.innerHTML=`<div class="result-card card"><div class="eyebrow">Simulazione completata</div><h1>${score.toLocaleString('it')} punti</h1><div class="stat-row"><div class="stat"><strong>${correct}</strong><span>Corrette</span></div><div class="stat"><strong>${wrong}</strong><span>Errate</span></div><div class="stat"><strong>${blank}</strong><span>Non date</span></div></div><p class="meta">Calcolo: ${correct} − (${wrong} × 0,33) = ${score.toLocaleString('it')}</p><div class="quiz-actions"><a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a></div></div>${reviewReport(rows)}`}
function reviewReport(rows){if(!rows.length)return'';const group=(type,label)=>{const list=rows.filter(r=>type==='correct'?r.correct:type==='wrong'?!r.correct&&!r.blank:r.blank);return `<section class="review-group"><div class="section-head"><h2>${label}</h2><span class="review-count">${list.length}</span></div>${list.length?list.map(r=>{const q=r.q,chosen=r.blank?'Non data':q.answers[r.choice],right=q.answers[q.correct];return `<details class="card review-item" ${type==='wrong'?'open':''}><summary><span class="review-badge ${type}">${type==='correct'?'✓':type==='wrong'?'✕':'—'}</span><span>${esc(q.text)}</span></summary>${q.image?`<img class="question-image mini" src="${esc(q.image)}" alt="Diagramma del quesito">`:''}<div class="review-answer"><span>La tua risposta</span><b>${esc(chosen)}</b></div><div class="review-answer correct-text"><span>Risposta corretta</span><b>${esc(right)}</b></div>${explanationMarkup(q.explanation)}</details>`}).join(''):'<div class="card meta">Nessuna domanda.</div>'}</section>`};return `<div class="review-report"><div class="section-head"><div><div class="eyebrow">Correzione completa</div><h1>Rivedi tutte le risposte</h1></div></div>${group('wrong','Risposte errate')}${group('blank','Non risposte')}${group('correct','Risposte corrette')}</div>`}
const formatTime=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;

function statsView(){nav('stats');const metrics=categoryMetrics(),officialStats=sessionSummary(['exam']),guidedStats=sessionSummary(['guided','guided-exam']),subjectStats=sessionSummary(['study','guided']),sessions=userState().sessions;app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Profilo personale</div><h1>Progressi e risultati</h1></div></div>${pieChartMarkup(metrics,'Preparazione complessiva')}${targetedRecommendationsMarkup(3)}<div class="section-head"><h2>Risultati dei quiz</h2></div><div class="quiz-result-summary"><div class="card"><span>Simulazioni ufficiali</span><strong>${officialStats.count}</strong><small>${officialStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${officialStats.averageAccuracy}% · migliore ${officialStats.bestScore?.toLocaleString('it')??'—'} pt`}</small></div><div class="card"><span>Quiz guidati</span><strong>${guidedStats.count}</strong><small>${guidedStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${guidedStats.averageAccuracy}%`}</small></div><div class="card"><span>Quiz per materia</span><strong>${subjectStats.count}</strong><small>${subjectStats.averageAccuracy===null?'Nessun risultato':`Precisione media ${subjectStats.averageAccuracy}%`}</small></div></div><div class="section-head"><h2>Andamento per materia</h2></div><div class="subject-stat-list">${categories.map(c=>{const m=categoryMetrics(c.id);return `<a class="card subject-stat" href="#category/${c.id}"><div><b>${esc(c.name)}</b><span>${m.accuracy===null?'Precisione da calcolare':`${m.accuracy}% precisione`} · ${coverageLabel(m)} classificato</span></div><div class="subject-mini-stats"><span class="known">${m.known} so</span><span class="review">${m.review} ripeti</span><span class="unknown">${m.unknown} non so</span><span class="unanswered">${m.toDo} da fare</span></div><div class="progress"><span style="width:${m.coverage}%"></span></div></a>`}).join('')}</div><div class="section-head"><h2>Cronologia di tutti i quiz</h2></div>${sessionHistoryMarkup(sessions)}`}

function adminView(){if(currentUser.role!=='admin')return home();nav('admin');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Solo amministratori</div><h1>Gestione utenti</h1></div></div><form class="card admin-form" id="newUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Password temporanea<input name="password" type="password" minlength="6" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="section-head"><h2>Utenti (${users.length})</h2></div><div class="user-list">${users.map(u=>`<div class="card user-row"><div><b>${esc(u.name)}</b><span>@${esc(u.username)} · ${u.role}</span></div><button class="ghost compact" data-toggle="${u.id}" ${u.id===currentUser.id?'disabled':''}>${u.active?'Disattiva':'Riattiva'}</button></div>`).join('')}</div>`;app.querySelector('#newUser').onsubmit=createUser;app.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const u=users.find(x=>x.id===b.dataset.toggle);u.active=!u.active;saveUsers();adminView()})}
async function createUser(e){e.preventDefault();const f=new FormData(e.currentTarget),username=String(f.get('username')).trim().toLowerCase();if(cloudMode){try{await cloudApi('./api/admin/users',{method:'POST',body:JSON.stringify({username,name:String(f.get('name')).trim(),email:String(f.get('email')||'').trim()||null,password:String(f.get('password')),role:String(f.get('role'))})});notify('Utente creato');settingsView()}catch(error){notify(error.message)}return}if(users.some(u=>u.username===username))return notify('Nome utente già esistente');users.push({id:crypto.randomUUID(),username,name:String(f.get('name')).trim(),role:String(f.get('role')),passwordHash:await hash(String(f.get('password'))),createdAt:new Date().toISOString(),active:true,state:{progress:{},sessions:[],categoryCursor:{},examCursor:{},examCount:0}});saveUsers();notify('Utente creato');settingsView()}

function dataView(){nav('data');if(cloudMode){app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Dataset centralizzato</div><h1>Banca dati</h1></div></div><div class="card data-box"><p><b>${official.length.toLocaleString('it')} quesiti ufficiali</b> disponibili sul server.</p><p class="meta">Nella versione cloud la banca dati è uguale per tutti e viene aggiornata insieme all'applicazione dal server Linux.</p></div>`;return}app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Dataset locale</div><h1>Gestione dati</h1></div></div><div class="card data-box"><p><b>${official.length.toLocaleString('it')} quesiti ufficiali</b> caricati.</p><p class="meta">È possibile aggiungere un file JSON autorizzato con id, category, text, answers e correct.</p><input type="file" id="file" accept="application/json,.json"><button class="primary" data-import>Importa dataset</button><button class="ghost" data-clear>Rimuovi aggiunte (${imported.length})</button></div>`;app.querySelector('[data-import]').onclick=importFile;app.querySelector('[data-clear]').onclick=()=>{imported=[];localStorage.removeItem(DATA);notify('Aggiunte rimosse');dataView()}}
async function importFile(){const file=app.querySelector('#file').files[0];if(!file)return notify('Scegli un file JSON');try{const rows=JSON.parse(await file.text());if(!Array.isArray(rows)||!rows.every(q=>q.id&&categories.some(c=>c.id===q.category)&&q.text&&Array.isArray(q.answers)&&Number.isInteger(q.correct)))throw Error();imported=rows;localStorage.setItem(DATA,JSON.stringify(rows));notify(`${rows.length} quesiti importati`);dataView()}catch{notify('File non valido')}}

function enhanceTrainerCard(){app.querySelector('.guided-card')?.remove()}
const setHeaderBase=setHeader;
setHeader=function(){setHeaderBase();if(currentUser&&!cloudMode&&!document.querySelector('[data-close-app]')){const button=document.createElement('button');button.className='ghost compact close-app';button.dataset.closeApp='';button.textContent='Chiudi app';button.onclick=closePortableApp;document.querySelector('.topbar').append(button)}};
async function closePortableApp(){if(!confirm('Vuoi chiudere Quiz 400 VVF 2026?'))return;try{await portableSync();const response=await fetch('./api/shutdown',{method:'POST'});if(!response.ok)throw Error();clearInterval(timerHandle);app.innerHTML='<div class="card result-card"><h1>App chiusa</h1><p>I dati sono stati salvati. Ora puoi chiudere questa scheda.</p></div>';document.querySelector('.bottom-nav').classList.add('hidden');setTimeout(()=>window.close(),500)}catch{notify('Chiusura automatica disponibile nella versione portatile')}}
const loginViewBase=loginView;
loginView=function(){loginViewBase();const label=app.querySelector('.auth-copy .eyebrow');if(label)label.textContent='Quiz 400 VVF 2026'};
function planSummary(plan){return EXAM_ORDER.map(id=>[id,normalizePlan(plan)[id]]).filter(([,count])=>count>0).map(([id,count])=>`${count} ${catName(id)}`).join(' · ')}
function presetManagerMarkup(){const st=userState(),active=activeExamPreset(),plan=normalizePlan(active?.plan||examConfig.examPlan||DEFAULT_EXAM_PLAN);return `<section class="card preset-manager"><div class="preset-title"><div><div class="eyebrow">Preferenze del tuo account</div><h2>Configurazioni quiz salvate</h2></div><span class="preset-active-badge">${active?esc(active.name):'Predefinita'}</span></div><p class="meta">Salva più composizioni da 40 domande e richiamale con un tocco. Restano separate per ogni utente e vengono incluse nei backup.</p><form id="personalExamPreset" class="personal-preset-form"><input type="hidden" name="presetId" value="${active?esc(active.id):''}"><label class="preset-name-field">Nome configurazione<input name="presetName" maxlength="40" placeholder="Es. Prova ufficiale" value="${active?esc(active.name):''}" required></label><div class="preset-fields">${categories.map(c=>`<label>${esc(c.name)}<input type="number" min="0" max="40" step="1" name="${c.id}" value="${plan[c.id]||0}"></label>`).join('')}</div><div class="settings-total">Totale: <strong data-preset-total>${planTotal(plan)}</strong>/40</div><div class="quiz-actions"><button class="primary" type="submit">${active?'Aggiorna e usa':'Salva e usa'}</button><button class="ghost" type="button" data-new-preset>Nuova configurazione</button><button class="ghost" type="button" data-use-default ${active?'':'disabled'}>Usa predefinita</button></div></form>${st.examPresets.length?`<div class="saved-presets"><h3>Le tue configurazioni</h3>${st.examPresets.map(item=>`<div class="preset-row ${item.id===st.activeExamPresetId?'active':''}"><div><b>${esc(item.name)}</b><span>${esc(planSummary(item.plan))}</span></div><div class="preset-row-actions"><button class="ghost compact" data-use-preset="${item.id}" ${item.id===st.activeExamPresetId?'disabled':''}>${item.id===st.activeExamPresetId?'In uso':'Usa'}</button><button class="ghost compact danger-text" data-delete-preset="${item.id}">Elimina</button></div></div>`).join('')}</div>`:''}</section>`}
function bindPresetManager(){const form=app.querySelector('#personalExamPreset');if(!form)return;const total=()=>[...form.querySelectorAll('.preset-fields input')].reduce((sum,input)=>sum+(Number(input.value)||0),0),refreshTotal=()=>app.querySelector('[data-preset-total]').textContent=total();form.querySelectorAll('.preset-fields input').forEach(input=>input.addEventListener('input',refreshTotal));form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),name=String(data.get('presetName')).trim(),id=String(data.get('presetId')||''),plan=normalizePlan(Object.fromEntries(categories.map(c=>[c.id,data.get(c.id)]))),st=userState();if(!name)return notify('Inserisci un nome per la configurazione');if(planTotal(plan)!==40)return notify(`Il totale deve essere 40: ora è ${planTotal(plan)}`);if(st.examPresets.some(item=>item.id!==id&&item.name.toLowerCase()===name.toLowerCase()))return notify('Esiste già una configurazione con questo nome');const existing=st.examPresets.find(item=>item.id===id);if(existing){existing.name=name;existing.plan=plan;existing.updatedAt=new Date().toISOString();st.activeExamPresetId=existing.id}else{const created={id:crypto.randomUUID(),name,plan,createdAt:new Date().toISOString()};st.examPresets.push(created);st.activeExamPresetId=created.id}saveUsers();notify('Configurazione salvata');simulationView()};app.querySelector('[data-new-preset]').onclick=()=>{form.elements.presetId.value='';form.elements.presetName.value='';form.querySelector('[type="submit"]').textContent='Salva e usa';form.elements.presetName.focus()};app.querySelector('[data-use-default]').onclick=()=>{userState().activeExamPresetId=null;saveUsers();notify('Configurazione predefinita attivata');simulationView()};app.querySelectorAll('[data-use-preset]').forEach(button=>button.onclick=()=>{userState().activeExamPresetId=button.dataset.usePreset;saveUsers();notify('Configurazione attivata');simulationView()});app.querySelectorAll('[data-delete-preset]').forEach(button=>button.onclick=()=>{const st=userState(),item=st.examPresets.find(entry=>entry.id===button.dataset.deletePreset);if(!item||!confirm(`Eliminare la configurazione “${item.name}”?`))return;st.examPresets=st.examPresets.filter(entry=>entry.id!==item.id);if(st.activeExamPresetId===item.id)st.activeExamPresetId=null;saveUsers();notify('Configurazione eliminata');simulationView()})}
function deepLearningProgressMarkup(summary,label){const percent=summary.total?Math.round(summary.mastered/summary.total*100):0;return `<div class="deep-learning-progress"><div><b>${esc(label)}</b><span>${summary.mastered.toLocaleString('it')} acquisite su ${summary.total.toLocaleString('it')} · ciclo ${summary.cycle}</span></div><div class="progress" aria-label="${percent}% completato"><span style="width:${percent}%"></span></div></div>`}
function deepLearningMarkup(){const settings=deepLearningSettings(),officialSummary=deepLearningTrackSummary('exam'),guidedSummary=deepLearningTrackSummary('guided-exam');return `<section class="card deep-learning-card ${settings.enabled?'active':''}"><div class="deep-learning-head"><div><div class="eyebrow">Ripasso adattivo personale</div><h2>Deep learning</h2></div><label class="switch-row"><input type="checkbox" data-deep-learning-toggle ${settings.enabled?'checked':''}><span class="switch-control" aria-hidden="true"></span><b>${settings.enabled?'Attivo':'Disattivato'}</b></label></div><p><strong>Quando è attivo, una domanda risposta correttamente non viene riproposta nelle prove successive finché non hai completato tutte le domande della stessa materia.</strong> Quelle errate o non risposte restano disponibili e hanno quindi più possibilità di tornare.</p><div class="deep-learning-note"><b>Come funziona</b><span>La simulazione resta sempre di 40 domande e rispetta la composizione scelta. Quando una materia completa il proprio ciclo, l'app la ricomincia automaticamente. Simulazione ufficiale e prova guidata hanno cicli separati.</span><span>Non invia dati a servizi di intelligenza artificiale: è un metodo di ripasso adattivo calcolato soltanto dalle tue risposte.</span></div><div class="deep-learning-stats">${deepLearningProgressMarkup(officialSummary,'Simulazione ufficiale')}${deepLearningProgressMarkup(guidedSummary,'Prova guidata')}</div><div class="quiz-actions"><button class="ghost danger-text" type="button" data-reset-deep-learning ${officialSummary.mastered||guidedSummary.mastered?'':'disabled'}>Azzera solo i cicli</button></div></section>`}
function bindDeepLearningControls(){const toggle=app.querySelector('[data-deep-learning-toggle]'),reset=app.querySelector('[data-reset-deep-learning]');if(toggle)toggle.onchange=()=>{const settings=deepLearningSettings();settings.enabled=toggle.checked;saveUsers();notify(toggle.checked?'Deep learning attivato':'Deep learning disattivato');simulationView()};if(reset)reset.onclick=()=>{if(!confirm('Azzerare i cicli Deep learning? Le statistiche generali e le risposte svolte non verranno eliminate.'))return;deepLearningSettings().tracks={};saveUsers();notify('Cicli Deep learning azzerati');simulationView()}}
function deepLearningResultMarkup(rows,track){if(!quiz?.deepLearning)return'';const correct=rows.filter(row=>row.correct).length,remaining=rows.length-correct,summary=deepLearningTrackSummary(track);return `<aside class="card deep-learning-result"><div class="eyebrow">Deep learning aggiornato</div><h2>${correct} ${correct===1?'domanda acquisita':'domande acquisite'}</h2><p>${remaining?`${remaining} ${remaining===1?'domanda resta':'domande restano'} nel ripasso perché errata o non risposta.`:'Tutte le risposte di questa prova sono entrate tra quelle acquisite.'}</p>${deepLearningProgressMarkup(summary,track==='exam'?'Simulazione ufficiale':'Prova guidata')}</aside>`}
deepLearningMarkup=function(){const settings=deepLearningSettings(),officialSummary=deepLearningTrackSummary('exam'),guidedSummary=deepLearningTrackSummary('guided-exam');return `<section class="card deep-learning-card ${settings.enabled?'active':''}"><div class="deep-learning-head"><div><div class="eyebrow">Ripasso adattivo personale</div><h2>Deep learning</h2></div><button class="switch-row" type="button" data-deep-learning-toggle aria-pressed="${settings.enabled}"><span class="switch-control" aria-hidden="true"></span><b>${settings.enabled?'Attivo':'Disattivato'}</b></button></div><p><strong>Quando è attivo, una domanda risposta correttamente non viene riproposta nelle prove successive finché non hai completato tutte le domande della stessa materia.</strong> Quelle errate o non risposte restano disponibili e hanno quindi più possibilità di tornare.</p><div class="deep-learning-note"><b>Come funziona</b><span>La simulazione resta sempre di 40 domande e rispetta la composizione scelta. Quando una materia completa il proprio ciclo, l'app la ricomincia automaticamente. Simulazione ufficiale e prova guidata hanno cicli separati.</span><span>Non invia dati a servizi di intelligenza artificiale: è un metodo di ripasso adattivo calcolato soltanto dalle tue risposte.</span></div><div class="deep-learning-stats">${deepLearningProgressMarkup(officialSummary,'Simulazione ufficiale')}${deepLearningProgressMarkup(guidedSummary,'Prova guidata')}</div><div class="quiz-actions"><button class="ghost danger-text" type="button" data-reset-deep-learning ${officialSummary.mastered||guidedSummary.mastered?'':'disabled'}>Azzera solo i cicli</button></div></section>`};
bindDeepLearningControls=function(){const toggle=app.querySelector('[data-deep-learning-toggle]'),reset=app.querySelector('[data-reset-deep-learning]');if(toggle)toggle.onclick=()=>{const settings=deepLearningSettings();settings.enabled=!settings.enabled;saveUsers();notify(settings.enabled?'Deep learning attivato':'Deep learning disattivato');simulationView()};if(reset)reset.onclick=()=>{if(!confirm('Azzerare i cicli Deep learning? Le statistiche generali e le risposte svolte non verranno eliminate.'))return;deepLearningSettings().tracks={};saveUsers();notify('Cicli Deep learning azzerati');simulationView()}};
const simulationViewBase=simulationView;
simulationView=function(){nav('simulation');if(resumeActiveQuiz())return;const composition=examPlan().map(([id,n])=>`<b>${n}</b> ${esc(catName(id))}`).join(' · '),active=activeExamPreset();app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card rotation-card"><h2>Estrazione sempre nuova</h2><p>Ogni prova usa data e ora correnti per mescolare le 40 domande. La rotazione viene salvata: anche dopo aver chiuso e riaperto l’app non riparte dallo stesso quiz e non ripete i quesiti già estratti finché la materia non completa il proprio ciclo.</p></div>${presetManagerMarkup()}<div class="card"><h2>Simulazione a tempo</h2><p>40 domande in 40 minuti, con cronometro sempre visibile, panoramica delle domande e consegna automatica allo scadere. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card composition guided-exam-card"><h2>Prova guidata con spiegazioni</h2><p>Stesse 40 domande, stesso cronometro e panoramica, con esito, soluzione e spiegazione immediati.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div><div class="card composition"><h2>Composizione attuale · ${active?esc(active.name):'Predefinita'}</h2><p>${composition}</p>${currentUser.role==='admin'?'<a class="button ghost" href="#settings">Modifica impostazione predefinita</a>':''}</div>`;bindPresetManager();app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam};
function settingsView(){if(currentUser.role!=='admin')return home();nav('settings');const total=planTotal(examConfig.examPlan);app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Solo amministratori</div><h1>Impostazioni</h1></div></div><form class="card admin-form" id="examSettings"><h2>Composizione predefinita delle 40 domande</h2><p class="meta">Questa configurazione si applica agli utenti che non hanno selezionato una preferenza personale. Imposta 0 per togliere una materia; la somma deve essere esattamente 40.</p>${categories.map(c=>`<label>${esc(c.name)}<input type="number" min="0" max="40" step="1" name="${c.id}" value="${Number(examConfig.examPlan?.[c.id])||0}"></label>`).join('')}<div class="settings-total">Totale attuale: <strong data-settings-total>${total}</strong>/40</div><div class="quiz-actions"><button class="primary" type="submit">Salva composizione predefinita</button><button class="ghost" type="button" data-reset-plan>Ripristina predefinita</button></div></form>`;const form=app.querySelector('#examSettings'),update=()=>app.querySelector('[data-settings-total]').textContent=[...form.querySelectorAll('input')].reduce((s,x)=>s+(Number(x.value)||0),0);form.querySelectorAll('input').forEach(x=>x.addEventListener('input',update));form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(categories.map(c=>[c.id,Math.max(0,Math.floor(Number(new FormData(form).get(c.id))||0))])),sum=Object.values(values).reduce((a,b)=>a+b,0);if(sum!==40)return notify(`Il totale deve essere 40: ora è ${sum}`);examConfig={...examConfig,examPlan:values};localStorage.setItem(CONFIG,JSON.stringify(examConfig));portableSync();notify('Composizione predefinita salvata');routeTo('simulation')};app.querySelector('[data-reset-plan]').onclick=()=>{examConfig={...examConfig,examPlan:{...DEFAULT_EXAM_PLAN}};localStorage.setItem(CONFIG,JSON.stringify(examConfig));portableSync();settingsView()}};
simulationView=function(){nav('simulation');if(resumeActiveQuiz())return;const composition=examPlan().map(([id,n])=>`<b>${n}</b> ${esc(catName(id))}`).join(' · '),active=activeExamPreset(),deepLearning=deepLearningSettings().enabled,deepBadge=deepLearning?'<span class="mode-deep-badge">Deep learning attivo</span>':'';app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Prove da 40 domande</div><h1>Scegli la modalità</h1></div></div><div class="card rotation-card"><h2>Estrazione sempre nuova</h2><p>Ogni prova usa data e ora correnti per mescolare le 40 domande. La rotazione viene salvata: anche dopo aver chiuso e riaperto l’app non riparte dallo stesso quiz.</p></div>${deepLearningMarkup()}${presetManagerMarkup()}<div class="simulation-mode-grid"><div class="card simulation-mode-card"><div class="mode-card-title"><h2>Simulazione a tempo</h2>${deepBadge}</div><p>40 domande in 40 minuti, con cronometro sempre visibile, panoramica delle domande e consegna automatica allo scadere. Nessuna correzione durante la prova.</p><div class="exam-rule"><strong>+1</strong><span>Corretta</span></div><div class="exam-rule"><strong>−0,33</strong><span>Errata</span></div><div class="exam-rule"><strong>0</strong><span>Non data</span></div><button class="primary exam-start" data-start-exam>Avvia simulazione 40/40</button></div><div class="card simulation-mode-card guided-exam-card"><div class="mode-card-title"><h2>Prova guidata con spiegazioni</h2>${deepBadge}</div><p>Stesse 40 domande, stesso cronometro e panoramica, con esito, soluzione e spiegazione immediati.</p><button class="secondary" data-start-guided-exam>Avvia prova guidata da 40</button></div></div><div class="card composition"><h2>Composizione attuale · ${active?esc(active.name):'Predefinita'}</h2><p>${composition}</p>${currentUser.role==='admin'?'<a class="button ghost" href="#settings">Modifica impostazione predefinita</a>':''}</div>`;bindDeepLearningControls();bindPresetManager();app.querySelector('[data-start-exam]').onclick=startExam;app.querySelector('[data-start-guided-exam]').onclick=startGuidedExam};
const settingsViewBase=settingsView;
function userSettingsMarkup(){if(cloudMode)return cloudUserSettingsMarkup();return `<section class="settings-users"><div class="section-head"><div><div class="eyebrow">Percorsi personali separati</div><h2>Utenti e statistiche</h2></div><span class="review-count">${users.length}</span></div><div class="card user-privacy-note"><b>Ogni utente ha il proprio percorso</b><p class="meta">Domande svolte, classificazione “La so / Da ripetere / Non la so”, rotazione dei quiz, simulazioni e punteggi sono salvati separatamente per ogni account.</p></div><form class="card admin-form" id="settingsNewUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Password temporanea<input name="password" type="password" minlength="6" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="user-list settings-user-list">${users.map(u=>{const progress=Object.values(u.state?.progress||{}),answered=progress.filter(item=>item.attempts).length,known=progress.filter(item=>item.status==='known').length,exams=(u.state?.sessions||[]).filter(item=>item.type==='exam').length;return `<div class="card user-row settings-user-row"><div><b>${esc(u.name)} ${u.id===currentUser.id?'<small class="current-user-label">Account attuale</small>':''}</b><span>@${esc(u.username)} · ${u.role==='admin'?'Amministratore':'Utente'} · ${u.active?'Attivo':'Disattivato'}</span><span class="user-progress-line"><strong>${answered}</strong> svolte · <strong>${known}</strong> conosciute · <strong>${exams}</strong> simulazioni</span></div><button class="ghost compact" data-settings-toggle="${u.id}" ${u.id===currentUser.id?'disabled':''}>${u.active?'Disattiva':'Riattiva'}</button></div>`}).join('')}</div></section>`}
settingsView=function(){settingsViewBase();if(currentUser.role!=='admin')return;const backupDescription=cloudMode?'Esporta account, progressi, statistiche e impostazioni del portale in un unico file protetto.':'Esporta utenti, progressi, statistiche, impostazioni e dataset importati in un unico file.';app.querySelector('#examSettings')?.insertAdjacentHTML('afterend',`<div class="card backup-card"><h2>Backup e ripristino</h2><p class="meta">${backupDescription}</p><div class="quiz-actions"><button class="secondary" type="button" data-export-backup>Scarica backup</button><label class="button ghost backup-file">Ripristina backup<input type="file" accept="application/json,.json" data-restore-backup hidden></label></div></div>`);const anchor=app.querySelector('.backup-card')||app.querySelector('#examSettings');anchor?.insertAdjacentHTML('afterend',userSettingsMarkup());app.querySelector('[data-export-backup]')?.addEventListener('click',exportBackup);app.querySelector('[data-restore-backup]')?.addEventListener('change',restoreBackup);app.querySelector('#settingsNewUser')?.addEventListener('submit',createUser);app.querySelectorAll('[data-settings-toggle]').forEach(button=>button.onclick=()=>{const user=users.find(item=>item.id===button.dataset.settingsToggle);user.active=!user.active;saveUsers();settingsView()})};
function exportBackup(){if(cloudMode){location.href='./api/admin/backup';notify('Preparazione backup cloud…');return}const payload={app:'Quiz 400 VVF 2026',version:1,createdAt:new Date().toISOString(),users,imported,config:examConfig},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`quiz-400-vvf-2026-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup creato')}
async function restoreBackup(e){const file=e.target.files?.[0];if(!file)return;if(cloudMode){if(!confirm('Il ripristino cloud sostituirà TUTTI gli utenti, progressi e impostazioni. Continuare?')){e.target.value='';return}if(prompt('Scrivi RIPRISTINA per confermare')!=='RIPRISTINA'){e.target.value='';return}try{await cloudApi('./api/admin/restore',{method:'POST',headers:{'X-Confirm-Restore':'RESTORE'},body:await file.text()});alert('Backup cloud ripristinato. Devi accedere nuovamente.');location.reload()}catch(error){e.target.value='';notify(error.message)}return}try{const backup=JSON.parse(await file.text()),plan=backup.config?.examPlan,total=plan&&Object.values(plan).reduce((s,n)=>s+(Number(n)||0),0);if(backup.app!=='Quiz 400 VVF 2026'||!Array.isArray(backup.users)||!Array.isArray(backup.imported)||!plan||total!==40)throw Error();if(!confirm('Il ripristino sostituirà utenti, progressi, statistiche e impostazioni attuali. Continuare?')){e.target.value='';return}users=backup.users;imported=backup.imported;examConfig=backup.config;localStorage.setItem(USERS,JSON.stringify(users));localStorage.setItem(DATA,JSON.stringify(imported));localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();alert('Backup ripristinato correttamente. L’app verrà ricaricata.');location.reload()}catch{e.target.value='';notify('Backup non valido o danneggiato')}}
const adminViewBase=adminView;
adminView=function(){if(currentUser.role!=='admin')return home();routeTo('settings')};

const amateurDisclaimerMarkup=()=>`<aside class="amateur-disclaimer" role="note"><b>Piattaforma gratuita e non ufficiale</b><span>Progetto puramente amatoriale creato a fini di studio. Non rappresenta, non è affiliato e non è approvato dal Ministero dell’Interno, dal Corpo Nazionale dei Vigili del Fuoco o da altri enti del concorso.</span></aside>`;
function publicAuthShell(title,copy,form){nav('home');setHeader();document.querySelector('.bottom-nav').classList.add('hidden');app.innerHTML=`<section class="auth-shell"><div class="auth-copy"><img class="auth-logo" data-brand-logo src="${esc(runtimeConfig.logoUrl||'logo-vvf.jpg')}" alt="Logo del portale"><div class="eyebrow">${esc(runtimeConfig.siteName||'Quiz 400 VVF 2026')}</div><h1>${esc(title)}</h1><p>${esc(copy)}</p>${amateurDisclaimerMarkup()}</div>${form}</section>`}
function registerView(){if(!cloudMode||!runtimeConfig.registrationEnabled)return loginView();publicAuthShell('Crea il tuo account','Registrati per mantenere progressi e statistiche sincronizzati nel cloud.',`<form class="card auth-card" id="registerForm"><label>Nome visualizzato<input name="name" autocomplete="name" minlength="2" required></label><label>Nome utente<input name="username" autocomplete="username" minlength="3" pattern="[a-zA-Z0-9._-]+" required></label><label>Email per recupero password<input name="email" type="email" autocomplete="email" required></label><p class="meta">Serve per ricevere il link se dimentichi la password.</p><label>Password<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Ripeti password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary">Registrati</button><a class="button ghost" href="#login">Hai già un account? Accedi</a><p class="meta">${esc(runtimeConfig.privacyNotice||'')}</p></form>`);app.querySelector('#registerForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(f.get('password')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{const result=await cloudApi('./api/auth/register',{method:'POST',body:JSON.stringify({name:String(f.get('name')).trim(),username:String(f.get('username')).trim(),email:String(f.get('email')).trim(),password:String(f.get('password'))})});notify(result.message);location.hash='login'}catch(error){notify(error.message)}}}
function forgotPasswordView(){if(!cloudMode)return loginView();if(!runtimeConfig.emailResetEnabled){publicAuthShell('Password dimenticata','Il recupero tramite email non è ancora disponibile.',`<div class="card auth-card"><div class="smtp-status warning"><b>Email non configurata</b><span>Nessun messaggio può essere inviato finché l’amministratore non configura il server SMTP. Contatta l’amministratore per ricevere una password temporanea.</span></div><a class="button primary" href="#login">Torna all'accesso</a></div>`);return}publicAuthShell('Password dimenticata','Inserisci nome utente o email. La risposta non rivelerà se un account esiste.',`<form class="card auth-card" id="forgotForm"><label>Nome utente o email<input name="account" autocomplete="username" required></label><button class="primary">Invia istruzioni</button><a class="button ghost" href="#login">Torna all'accesso</a><p class="meta">Se l’account ha un indirizzo email associato riceverai un link temporaneo.</p></form>`);app.querySelector('#forgotForm').onsubmit=async event=>{event.preventDefault();try{const result=await cloudApi('./api/auth/forgot-password',{method:'POST',body:JSON.stringify({account:String(new FormData(event.currentTarget).get('account')).trim()})});app.querySelector('#forgotForm').innerHTML=`<h2>Richiesta ricevuta</h2><p>${esc(result.message)}</p><a class="button primary" href="#login">Torna all'accesso</a>`}catch(error){notify(error.message)}}}
function resetPasswordView(){if(!cloudMode)return loginView();const token=decodeURIComponent(location.hash.split('/')[1]||'');publicAuthShell('Scegli una nuova password','Il link di recupero può essere usato una sola volta.',`<form class="card auth-card" id="resetForm"><label>Nuova password<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Ripeti password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></label><button class="primary">Reimposta password</button><a class="button ghost" href="#login">Torna all'accesso</a></form>`);app.querySelector('#resetForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(!token)return notify('Link di recupero mancante');if(f.get('password')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{await cloudApi('./api/auth/reset-password',{method:'POST',body:JSON.stringify({token,password:String(f.get('password'))})});history.replaceState({},'',location.pathname+'#login');notify('Password aggiornata. Ora puoi accedere');router()}catch(error){notify(error.message)}}}
function changePasswordView(){if(!cloudMode||!currentUser)return loginView();nav('home');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Sicurezza account</div><h1>${currentUser.mustChangePassword?'Cambia la password temporanea':'Cambia password'}</h1></div></div><form class="card auth-card cloud-narrow" id="changePasswordForm"><label>Password attuale<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nuova password<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label><label>Ripeti nuova password<input name="confirmPassword" type="password" minlength="10" autocomplete="new-password" required></label><button class="primary">Salva nuova password</button>${currentUser.mustChangePassword?'':'<a class="button ghost" href="#account">Annulla</a>'}</form>`;app.querySelector('#changePasswordForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(f.get('newPassword')!==f.get('confirmPassword'))return notify('Le password non coincidono');try{await cloudApi('./api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:String(f.get('currentPassword')),new_password:String(f.get('newPassword'))})});currentUser.mustChangePassword=false;const record=userRecord();if(record)record.mustChangePassword=false;notify('Password aggiornata');location.hash='home'}catch(error){notify(error.message)}}}
function accountView(){if(!cloudMode||!currentUser)return home();nav('home');app.innerHTML=`<div class="section-head"><div><div class="eyebrow">Profilo personale</div><h1>Il tuo account</h1></div></div><form class="card auth-card cloud-narrow" id="profileForm"><label>Nome visualizzato<input name="name" value="${esc(currentUser.name)}" minlength="2" required></label><label>Nome utente<input value="${esc(currentUser.username||'')}" disabled></label><label>Email per recupero password<input name="email" type="email" value="${esc(currentUser.email||'')}"></label><label>Tema dell’interfaccia<select name="theme"><option value="light" ${userState().theme==='light'?'selected':''}>Chiaro</option><option value="dark" ${userState().theme==='dark'?'selected':''}>Scuro</option><option value="system" ${userState().theme==='system'?'selected':''}>Come il dispositivo</option></select></label><p class="meta">Tema, configurazioni delle prove, rotazione delle domande, progressi e statistiche appartengono solo a questo account.</p><button class="primary">Salva profilo e preferenze</button><a class="button ghost" href="#change-password">Cambia password</a></form>`;app.querySelector('#profileForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{const result=await cloudApi('./api/auth/profile',{method:'PUT',body:JSON.stringify({name:String(f.get('name')).trim(),email:String(f.get('email')).trim()||null})});currentUser.name=result.user.name;currentUser.email=result.user.email;Object.assign(userRecord(),result.user);userState().theme=String(f.get('theme'));applyTheme();await saveUsers();setHeader();notify('Profilo e tema aggiornati')}catch(error){notify(error.message)}}}

function cloudUserSettingsMarkup(){return `<section class="settings-users cloud-users"><div class="section-head"><div><div class="eyebrow">Controllo centralizzato</div><h2>Utenti e statistiche</h2></div><span class="review-count" data-cloud-user-count>…</span></div><div class="card user-privacy-note"><b>L'admin vede attività e risultati, non le password</b><p class="meta">Per ogni utente puoi consultare precisione, domande da ripetere, copertura per materia e risultati dei diversi tipi di quiz.</p></div><form class="card admin-form" id="settingsNewUser"><h2>Crea utente</h2><label>Nome visualizzato<input name="name" required></label><label>Nome utente<input name="username" required></label><label>Email<input name="email" type="email"></label><label>Password temporanea<input name="password" type="password" minlength="10" required></label><label>Ruolo<select name="role"><option value="user">Utente</option><option value="admin">Amministratore</option></select></label><button class="primary">Crea account</button></form><div class="cloud-totals" data-cloud-totals></div><div class="user-list settings-user-list" data-cloud-users><div class="card meta">Caricamento utenti…</div></div></section>`}
function cloudUserCard(user){const s=user.statistics||{};return `<article class="card cloud-user-card ${user.active?'':'inactive'}"><div class="cloud-user-head"><div><h3>${esc(user.name)} ${user.id===currentUser.id?'<small class="current-user-label">Account attuale</small>':''}</h3><p>@${esc(user.username)} · ${user.role==='admin'?'Amministratore':'Utente'} · ${user.active?'Attivo':'Disattivato'}</p><p class="meta">${user.email?`Email: ${esc(user.email)}`:'⚠ Email di recupero non impostata'} · Ultimo accesso: ${user.lastLoginAt?new Date(user.lastLoginAt).toLocaleString('it'):'mai'}</p></div><span class="cloud-user-role">${user.role==='admin'?'Admin':'Utente'}</span></div><div class="cloud-user-stats"><span><b>${s.answered||0}</b>Domande svolte</span><span><b>${s.fortyQuizzes||0}</b>Prove da 40</span><span><b>${fmtMetric(s.averageFortyScore)}</b>Media 40 /40</span><span><b>${s.subjectQuizzes||0}</b>Quiz argomenti</span><span><b>${s.averageSubjectAccuracy==null?'—':`${fmtMetric(s.averageSubjectAccuracy,1)}%`}</b>Media argomenti</span><span><b>${s.review||0}</b>Da ripetere</span></div><div class="cloud-user-actions"><button class="secondary compact" data-cloud-stats="${user.id}">Statistiche</button><button class="ghost compact" data-cloud-reset="${user.id}" ${user.id===currentUser.id?'disabled':''}>Reset password</button><button class="ghost compact" data-cloud-role="${user.id}" ${user.id===currentUser.id?'disabled':''}>${user.role==='admin'?'Rendi utente':'Rendi admin'}</button><button class="ghost compact" data-cloud-toggle="${user.id}" ${user.id===currentUser.id?'disabled':''}>${user.active?'Disattiva':'Riattiva'}</button><button class="ghost compact danger-text" data-cloud-delete="${user.id}" ${user.id===currentUser.id?'disabled':''}>Elimina</button></div></article>`}
async function loadCloudAdminUsers(){try{const result=await cloudApi('./api/admin/users');cloudAdminUsers=result.users;app.querySelector('[data-cloud-user-count]').textContent=result.totals.users;app.querySelector('[data-cloud-totals]').innerHTML=`<div class="cloud-admin-summary"><div class="card stat"><strong>${result.totals.users}</strong><span class="meta">Account</span></div><div class="card stat"><strong>${result.totals.active}</strong><span class="meta">Attivi</span></div><div class="card stat"><strong>${result.totals.fortyQuizzes||0}</strong><span class="meta">Prove da 40</span></div><div class="card stat"><strong>${fmtMetric(result.totals.averageFortyScore)}</strong><span class="meta">Media 40 /40</span></div><div class="card stat"><strong>${result.totals.subjectQuizzes||0}</strong><span class="meta">Quiz argomenti</span></div><div class="card stat"><strong>${result.totals.averageSubjectAccuracy==null?'—':`${fmtMetric(result.totals.averageSubjectAccuracy,1)}%`}</strong><span class="meta">Media argomenti</span></div></div>`;app.querySelector('[data-cloud-users]').innerHTML=result.users.map(cloudUserCard).join('')||'<div class="card meta">Nessun utente.</div>';bindCloudUserActions()}catch(error){app.querySelector('[data-cloud-users]').innerHTML=`<div class="notice">${esc(error.message)}</div>`}}
function bindCloudUserActions(){app.querySelectorAll('[data-cloud-stats]').forEach(button=>button.onclick=()=>showCloudStatistics(button.dataset.cloudStats));app.querySelectorAll('[data-cloud-toggle]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudToggle);if(!user)return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({active:!user.active})});notify(user.active?'Utente disattivato':'Utente riattivato');loadCloudAdminUsers()}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-role]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudRole);if(!user||!confirm(`${user.role==='admin'?'Rimuovere i permessi amministratore da':'Rendere amministratore'} ${user.name}?`))return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({role:user.role==='admin'?'user':'admin'})});notify('Ruolo aggiornato');loadCloudAdminUsers()}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-reset]').forEach(button=>button.onclick=async()=>{if(!confirm('Generare una nuova password temporanea e scollegare questo utente?'))return;try{const result=await cloudApi(`./api/admin/users/${button.dataset.cloudReset}/reset-password`,{method:'POST',body:'{}'});alert(`Password temporanea (visibile una sola volta):\n\n${result.temporaryPassword}\n\nComunicala all’utente in modo sicuro.`)}catch(error){notify(error.message)}});app.querySelectorAll('[data-cloud-delete]').forEach(button=>button.onclick=async()=>{const user=cloudAdminUsers.find(item=>item.id===button.dataset.cloudDelete);if(!user||!confirm(`Eliminare definitivamente ${user.name} e tutte le sue statistiche?`))return;if(prompt(`Scrivi ${user.username} per confermare`)!==user.username)return;try{await cloudApi(`./api/admin/users/${user.id}`,{method:'DELETE'});notify('Account eliminato');loadCloudAdminUsers()}catch(error){notify(error.message)}})}
async function showCloudStatistics(userId){try{const result=await cloudApi(`./api/admin/users/${userId}/statistics`),summary=result.summary,categoriesMarkup=Object.entries(result.categories).map(([id,s])=>`<div class="cloud-category-stat"><b>${esc(catName(id))}</b><span>${s.accuracy==null?'—':`${s.accuracy}%`} precisione complessiva · ${s.known} note · ${s.review} da ripetere · ${s.unknown} non note · ${s.toDo??s.unanswered} da fare</span><span class="quiz-average-line">${s.quizCount?`<strong>${s.quizCount}</strong> quiz completati · media <strong>${fmtMetric(s.averageQuizScore)} pt</strong> su ${fmtMetric(s.averageQuizQuestions,1)} domande · <strong>${fmtMetric(s.averageQuizAccuracy,1)}%</strong>`:'Nessun quiz completo registrato per questa materia.'}</span></div>`).join(''),sessions=result.recentSessions.slice(0,20).map(session=>`<div class="history"><b>${esc(sessionTypeLabel(session.type))} · ${session.at?new Date(session.at).toLocaleString('it'):''}</b><span>${session.accuracy==null?'—':`${session.accuracy}%`} · ${session.score??'—'} punti · ${session.correct||0}✓ ${session.wrong||0}✕ ${session.blank||0}—</span></div>`).join('');const overlay=document.createElement('div');overlay.className='update-dialog-backdrop';overlay.innerHTML=`<section class="card update-dialog cloud-stats-dialog"><div class="eyebrow">Statistiche complete</div><h2>${esc(result.user.name)} · @${esc(result.user.username)}</h2><h3>Medie dei quiz</h3><div class="cloud-average-grid"><div class="stat"><strong>${summary.fortyQuizzes||0}</strong><span>Prove da 40</span></div><div class="stat highlight"><strong>${fmtMetric(summary.averageFortyScore)}</strong><span>Media punti /40</span></div><div class="stat"><strong>${summary.averageFortyAccuracy==null?'—':`${fmtMetric(summary.averageFortyAccuracy,1)}%`}</strong><span>Precisione prove 40</span></div><div class="stat"><strong>${summary.subjectQuizzes||0}</strong><span>Quiz argomenti</span></div><div class="stat highlight"><strong>${summary.averageSubjectAccuracy==null?'—':`${fmtMetric(summary.averageSubjectAccuracy,1)}%`}</strong><span>Media argomenti</span></div><div class="stat"><strong>${fmtMetric(summary.averageSubjectScore)}</strong><span>Media punti argomenti</span></div></div><h3>Preparazione</h3><div class="stat-row four"><div class="stat"><strong>${summary.answered}</strong><span>Domande svolte</span></div><div class="stat"><strong>${summary.known}</strong><span>Conosciute</span></div><div class="stat"><strong>${summary.review}</strong><span>Da ripetere</span></div><div class="stat"><strong>${summary.unknown}</strong><span>Non note</span></div></div><h3>Per materia</h3><div class="cloud-category-list">${categoriesMarkup||'<p class="meta">Nessun progresso.</p>'}</div><h3>Ultime sessioni</h3><div>${sessions||'<p class="meta">Nessuna sessione completata.</p>'}</div><button class="primary" data-close-stats>Chiudi</button></section>`;document.body.append(overlay);overlay.querySelector('[data-close-stats]').onclick=()=>overlay.remove();overlay.onclick=event=>{if(event.target===overlay)overlay.remove()}}catch(error){notify(error.message)}}

function cloudSettingsMarkup(){return `<section class="cloud-settings"><div class="section-head"><div><div class="eyebrow">Server Linux e dominio pubblico</div><h2>Impostazioni Cloud</h2></div></div><form class="card cloud-settings-form" id="cloudSettingsForm"><fieldset><legend>Portale</legend><label>Nome portale<input name="siteName" required></label><label>URL pubblico<input name="publicUrl" type="url" placeholder="https://nome.duckdns.org"></label><label class="check-label"><input name="registrationEnabled" type="checkbox"> Consenti registrazione pubblica</label><label>Durata sessione (giorni)<input name="sessionDays" type="number" min="1" max="365"></label><label>Scadenza link recupero (minuti)<input name="resetTokenMinutes" type="number" min="10" max="1440"></label><label class="full">Informativa breve<textarea name="privacyNotice"></textarea></label></fieldset><fieldset class="network-settings"><legend>Porte e HTTPS</legend><div class="network-status full" data-network-status>Caricamento configurazione rete…</div><div class="port-control full hidden" data-port-control><label>Nuova porta backend<input name="deploymentAppPort" type="number" min="1024" max="65535"></label><button class="secondary" type="button" data-change-port>Controlla e applica porta</button><p class="meta" data-port-control-status></p></div><p class="meta full">Il pubblico continua a usare HTTPS sulla porta 443. Il controllo protetto sul server verifica che la nuova porta sia libera, aggiorna il backend e ricarica il reverse proxy; in caso di errore ripristina la configurazione precedente.</p></fieldset><fieldset><legend>DuckDNS</legend><label class="check-label"><input name="duckdnsEnabled" type="checkbox"> Aggiornamento DuckDNS attivo</label><label>Dominio<input name="duckdnsDomain" placeholder="mioquiz o mioquiz.duckdns.org"></label><label>Token DuckDNS<input name="duckdnsToken" type="password" placeholder="Lascia vuoto per mantenere quello salvato"></label><label>Intervallo (minuti)<input name="duckdnsIntervalMinutes" type="number" min="5" max="1440"></label><p class="meta full" data-duckdns-status></p><button class="ghost" type="button" data-test-duckdns>Prova DuckDNS</button></fieldset><fieldset><legend>Email e password dimenticata</legend><label class="check-label"><input name="smtpEnabled" type="checkbox"> Invio email attivo</label><label>Server SMTP<input name="smtpHost"></label><label>Porta<input name="smtpPort" type="number" min="1" max="65535"></label><label>Nome utente SMTP<input name="smtpUsername"></label><label>Password SMTP<input name="smtpPassword" type="password" placeholder="Lascia vuoto per mantenerla"></label><label>Email mittente<input name="smtpFromEmail" type="email"></label><label class="check-label"><input name="smtpUseTls" type="checkbox"> Usa STARTTLS</label><button class="ghost" type="button" data-test-email>Invia email di prova all'admin</button></fieldset><button class="primary" type="submit">Salva impostazioni cloud</button></form></section>`}
async function loadCloudSettings(){try{const s=await cloudApi('./api/admin/settings'),form=app.querySelector('#cloudSettingsForm');for(const [name,value] of Object.entries({siteName:s.siteName,publicUrl:s.publicUrl,sessionDays:s.sessionDays,resetTokenMinutes:s.resetTokenMinutes,privacyNotice:s.privacyNotice,duckdnsDomain:s.duckdnsDomain,duckdnsIntervalMinutes:s.duckdnsIntervalMinutes,smtpHost:s.smtpHost,smtpPort:s.smtpPort,smtpUsername:s.smtpUsername,smtpFromEmail:s.smtpFromEmail,deploymentAppPort:s.deploymentAppPort})){if(form.elements[name])form.elements[name].value=value??''}for(const [name,value] of Object.entries({registrationEnabled:s.registrationEnabled,duckdnsEnabled:s.duckdnsEnabled,smtpEnabled:s.smtpEnabled,smtpUseTls:s.smtpUseTls})){form.elements[name].checked=Boolean(value)}form.elements.duckdnsToken.placeholder=s.duckdnsTokenConfigured?'Token già salvato · lascia vuoto per mantenerlo':'Inserisci token DuckDNS';form.elements.smtpPassword.placeholder=s.smtpPasswordConfigured?'Password già salvata · lascia vuoto per mantenerla':'Inserisci password SMTP';const networkStatus=form.querySelector('[data-network-status]');networkStatus.innerHTML=s.deploymentProxyMode==='external'?`<b>Reverse proxy esistente</b><span>HTTPS pubblico: porta 443 → backend ${esc(s.deploymentBindAddress)}:${Number(s.deploymentAppPort)}</span>`:`<b>Proxy HTTPS incluso</b><span>HTTP ${Number(s.deploymentHttpPort)} · HTTPS ${Number(s.deploymentHttpsPort)} · backend locale ${Number(s.deploymentAppPort)}</span>`;const portControl=form.querySelector('[data-port-control]'),portStatus=form.querySelector('[data-port-control-status]');portControl?.classList.toggle('hidden',!s.portControl?.available);if(portStatus)portStatus.textContent=portControlStatusLabel(s.portControl);form.querySelector('[data-duckdns-status]').textContent=s.duckdnsLastStatus?.at?`Ultimo controllo: ${new Date(s.duckdnsLastStatus.at).toLocaleString('it')} · ${s.duckdnsLastStatus.ok?'OK':'Errore'} · ${s.duckdnsLastStatus.response||''}`:'Nessun aggiornamento DuckDNS eseguito.';form.onsubmit=saveCloudSettings;form.querySelector('[data-change-port]').onclick=()=>requestCloudPortChange(form,s);form.querySelector('[data-test-duckdns]').onclick=async()=>{try{const result=await cloudApi('./api/admin/settings/test-duckdns',{method:'POST'});notify(result.ok?'DuckDNS aggiornato correttamente':'DuckDNS non aggiornato');loadCloudSettings()}catch(error){notify(error.message)}};form.querySelector('[data-test-email]').onclick=async()=>{try{const result=await cloudApi('./api/admin/settings/test-email',{method:'POST'});notify(result.message)}catch(error){notify(error.message)}}}catch(error){notify(error.message)}}
function portControlStatusLabel(status){if(!status?.available)return'Il cambio diretto non è installato su questo server.';if(status.state==='applying'||status.state==='queued')return`Cambio porta in corso${status.port?` verso ${status.port}`:''}…`;if(status.state==='applied')return`Ultimo cambio completato${status.port?`: backend sulla porta ${status.port}`:''}.`;if(status.state==='error')return`Ultimo cambio non riuscito: ${status.message||'configurazione precedente ripristinata'}`;return'Controllo porte pronto.'}
async function requestCloudPortChange(form,current){const port=Number(form.elements.deploymentAppPort.value);if(!Number.isInteger(port)||port<1024||port>65535)return notify('Scegli una porta tra 1024 e 65535');if(port===Number(current.deploymentAppPort))return notify('Questa porta è già attiva');if(!confirm(`Cambiare la porta backend da ${current.deploymentAppPort} a ${port}?\n\nIl portale verrà riavviato per pochi secondi. La porta pubblica HTTPS resterà 443.`))return;const button=form.querySelector('[data-change-port]');button.disabled=true;button.textContent='Richiesta in corso…';try{await cloudApi('./api/admin/network/apply',{method:'POST',body:JSON.stringify({app_port:port})});const status=form.querySelector('[data-port-control-status]');status.textContent=`Riavvio del backend sulla porta ${port}…`;await waitForCloudPortChange(port,status)}catch(error){button.disabled=false;button.textContent='Controlla e applica porta';notify(error.message)}}
async function waitForCloudPortChange(port,status){const deadline=Date.now()+180000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,2200));try{const settings=await cloudApi(`./api/admin/settings?t=${Date.now()}`);if(Number(settings.deploymentAppPort)===port){status.textContent=`Porta ${port} attiva. Ricarico il pannello…`;setTimeout(()=>location.reload(),700);return}if(settings.portControl?.state==='error')throw Error(settings.portControl.message||'Cambio porta non riuscito')}catch(error){if(error.message&&error.message!=='Richiesta non riuscita')status.textContent=error.message}}status.textContent='Il riavvio richiede più tempo del previsto. Ricarica la pagina tra poco.'}
async function saveCloudSettings(event){event.preventDefault();const f=new FormData(event.currentTarget),payload={site_name:String(f.get('siteName')).trim(),registration_enabled:f.get('registrationEnabled')==='on',public_url:String(f.get('publicUrl')).trim(),session_days:Number(f.get('sessionDays')),reset_token_minutes:Number(f.get('resetTokenMinutes')),privacy_notice:String(f.get('privacyNotice')).trim(),duckdns_enabled:f.get('duckdnsEnabled')==='on',duckdns_domain:String(f.get('duckdnsDomain')).trim(),duckdns_token:String(f.get('duckdnsToken')),duckdns_interval_minutes:Number(f.get('duckdnsIntervalMinutes')),smtp_enabled:f.get('smtpEnabled')==='on',smtp_host:String(f.get('smtpHost')).trim(),smtp_port:Number(f.get('smtpPort')),smtp_username:String(f.get('smtpUsername')).trim(),smtp_password:String(f.get('smtpPassword')),smtp_from_email:String(f.get('smtpFromEmail')).trim()||null,smtp_use_tls:f.get('smtpUseTls')==='on'};try{await cloudApi('./api/admin/settings',{method:'PUT',body:JSON.stringify(payload)});runtimeConfig={...runtimeConfig,siteName:payload.site_name,registrationEnabled:payload.registration_enabled,privacyNotice:payload.privacy_notice,emailResetEnabled:payload.smtp_enabled};document.querySelector('.brand>span:last-child').textContent=payload.site_name;notify('Impostazioni cloud salvate');loadCloudSettings()}catch(error){notify(error.message)}}

function brandingSettingsMarkup(){return `<section class="branding-settings card"><div><div class="eyebrow">Aspetto globale</div><h2>Logo del portale</h2><p class="meta">Il logo viene applicato senza deformazioni nell’intestazione, nelle schermate di accesso e nell’icona installabile. Formati JPEG, PNG o WebP; massimo 1 MB.</p></div><div class="branding-editor"><img data-brand-preview src="${esc(currentLogoUrl())}" alt="Anteprima logo"><div><label>Scegli un nuovo logo<input type="file" data-brand-file accept="image/jpeg,image/png,image/webp"></label><div class="quiz-actions"><button class="secondary" type="button" data-brand-save disabled>Applica ovunque</button><button class="ghost" type="button" data-brand-reset>Ripristina predefinito</button></div><p class="meta" data-brand-status></p></div></div></section>`}
function bindBrandingSettings(){const section=app.querySelector('.branding-settings');if(!section)return;const input=section.querySelector('[data-brand-file]'),preview=section.querySelector('[data-brand-preview]'),save=section.querySelector('[data-brand-save]'),status=section.querySelector('[data-brand-status]');let selected=null;input.onchange=()=>{const file=input.files?.[0];selected=null;save.disabled=true;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1024*1024){input.value='';status.textContent='Il file deve essere JPEG, PNG o WebP e pesare al massimo 1 MB.';return}const reader=new FileReader();reader.onload=()=>{selected=String(reader.result);preview.src=selected;save.disabled=false;status.textContent=`Pronto: ${file.name} · ${Math.ceil(file.size/1024)} KB`};reader.readAsDataURL(file)};save.onclick=async()=>{if(!selected)return;save.disabled=true;try{if(cloudMode){const result=await cloudApi('./api/admin/branding/logo',{method:'POST',body:JSON.stringify({data_url:selected})});runtimeConfig.logoCustomized=true;applyBranding(result.logoUrl)}else{examConfig.brandLogoDataUrl=selected;localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();applyBranding(selected)}preview.src=currentLogoUrl();status.textContent='Logo applicato in tutto il portale.';notify('Logo aggiornato')}catch(error){save.disabled=false;status.textContent=error.message}};section.querySelector('[data-brand-reset]').onclick=async()=>{if(!confirm('Ripristinare il logo nero predefinito?'))return;try{if(cloudMode){const result=await cloudApi('./api/admin/branding/logo',{method:'DELETE'});runtimeConfig.logoCustomized=false;applyBranding(result.logoUrl)}else{delete examConfig.brandLogoDataUrl;localStorage.setItem(CONFIG,JSON.stringify(examConfig));await portableSync();applyBranding('logo-vvf.jpg')}selected=null;input.value='';save.disabled=true;preview.src=currentLogoUrl();status.textContent='Logo predefinito ripristinato.';notify('Logo ripristinato')}catch(error){status.textContent=error.message}}}

const loadCloudSettingsBase=loadCloudSettings;
