finishGuided=function(reason='completed'){clearInterval(timerHandle);if(!quiz||quiz.finished)return;quiz.finished=true;const rows=quiz.pool.map(q=>quiz.history[q.id]||{choice:null,blank:true,correct:false,q}),timed=isTimedFortyQuiz();if(timed){for(const row of rows){const p=progressFor(row.q.id);if(row.blank){p.skipped++;if(!p.attempts)p.status='unanswered'}else{p.attempts++;if(row.correct){p.correct++;p.status=p.correct>=2&&p.wrong===0?'known':'review'}else{p.wrong++;p.status='review'}}p.lastAt=new Date().toISOString();userState().progress[row.q.id]=p}}const session=recordSession(quiz.mode==='guided-exam'?'guided-exam':'guided',rows,{timedOut:reason==='timeout',generatedAt:quiz.generatedAt});timed?clearActiveQuiz():persist();app.innerHTML=resultCard(reason==='timeout'?'Tempo scaduto · prova guidata conclusa':'Prova guidata completata',session.correct,session.wrong,session.blank,'<a class="button primary" href="#simulation">Nuova prova</a><a class="button ghost" href="#stats">Statistiche</a>')+reviewReport(rows);window.scrollTo({top:0,behavior:'instant'})};
